import { SwimlaneElement, css, html, svg, unsafeCSS } from '@swimlane/swimlane-element@1';

const FIELD1 = 'sla-total-hours';
const FIELD2 = 'sla-used-minutes';

const COLOR_GREY = '#5A6884';
const COLOR_GREEN = '#17B9B8';
const COLOR_BLUE = '#1483FF';
const COLOR_YELLOW = '#B95900';
const COLOR_RED = '#FF4514';

const widgetCss = css`
  .slim-widget--container {
    height: 60px;
    width: 100%;
    display: flex;
    align-items: center;
  }
  .sla--container {
    height: 35px;
    width: 100%;
    border-left: 2px solid var(--borderColor);
    display: flex;
    flex-direction: column;
  }

  .progress-bar--container {
    height: 50%;
    width: 80%;
    margin-left: 10px;
  }
  .progress-bar--container svg {
    overflow: visible;
    margin-left: 2px;
  }

  .text--container {
    height: 50%;
    width: 90%;
    margin-left: 10px;
    min-height: 50%;
    color: #818fa9;
    white-space: nowrap;
    font-weight: normal;
    display: flex;
    align-items: baseline;
    z-index: 9999;
  }
  .text--container .label-text {
    font-size: 1em;
  }
  .text--container .total-time {
    font-style: italic;
    font-size: 1em;
  }
  .text--container h2.usage-time {
    margin: 0 5px;
    font-size: 1.2em;
    color: #cdd2dd;
  }
  .no-data--container {
    color: #818fa9;
    margin: 10px;
  }
`;
function formatTime(usedMinutes) {
  let mins = 0;
  let hours = 0;
  if (usedMinutes >= 60) {
    hours = Math.floor(usedMinutes / 60);
    mins = usedMinutes % 60;
    mins = mins < 10 ? `0${mins}` : mins;
    hours = hours < 10 ? `0${hours}` : hours;
  } else {
    mins = usedMinutes < 10 ? `0${usedMinutes}` : usedMinutes;
    hours = '00';
  }
  return `${hours}:${mins}`;
}

function isNullOrUndefined(value) {
  return value === null || value === 'null' || typeof value === 'undefined';
}

const template = (totalHours, minutes, innerWidth) => {
  const totalHoursToMinutes = totalHours * 60;
  const percentage = (minutes / totalHoursToMinutes) * 100;
  let progressColor = COLOR_GREY; // default
  if (percentage > 0 && percentage <= 25) {
    progressColor = COLOR_GREEN;
  } else if (percentage > 25 && percentage <= 50) {
    progressColor = COLOR_BLUE;
  } else if (percentage > 50 && percentage < 100) {
    progressColor = COLOR_YELLOW;
  } else if (percentage >= 100) {
    progressColor = COLOR_RED;
  }

  let totalHoursText = totalHours > 1 ? `of ${totalHours} Hours` : `of ${totalHours} Hour`;

  // overtime
  let isOverTime;

  if (minutes > totalHoursToMinutes) {
    isOverTime = true;
  } else {
    isOverTime = false;
  }
  //console.log("isOverTime: "+ isOverTime)
  let barLength;
  if (isOverTime){
    barLength = innerWidth
  } 
  else
  {
    barLength =
      minutes && minutes % totalHoursToMinutes === 0
        ? innerWidth
        : ((minutes % totalHoursToMinutes) / totalHoursToMinutes) * innerWidth;
    console.log("minutes: "+ minutes)
    console.log("totalHoursToMinutes: " + totalHoursToMinutes)
  }
  const isDataUnavailable = isNullOrUndefined(totalHours) || isNullOrUndefined(minutes);
  return html`
    <div
      class="sla--container"
      style="--borderColor:${!isDataUnavailable && percentage >= 100 ? COLOR_RED : '#2B3240'}"
    >
      ${isDataUnavailable
        ? html`
            <div class="no-data--container">No SLA Data Available</div>
          `
        : html`
      <div class="text--container">
        <div class="label-text"> SLA Usage </div>
        <h2 class="usage-time">${formatTime(minutes)}</h2>
        <div class="total-time"> ${totalHoursText} </div>
      </div>
      <div class="progress-bar--container">
        <svg
          width="100%"
          height="100%"
        >
          <circle id="tiny-circle" cx="${innerWidth}" cy="10" r="${isOverTime ? 2.5 : 2}" fill="${
            progressColor === COLOR_RED ? COLOR_RED : COLOR_GREY
          }" />
          <line
            x1="0",
            y1="10",
            x2="${innerWidth}",
            y2="10"
            stroke="${isOverTime ? 'none' : COLOR_GREY}"
            stroke-width="2"
            fill-rule="nonzero"
          ></line>
          <line
            x1="0",
            y1="10",
            x2="${barLength}",
            y2="10"
            class="line"
            class="Oval-Copy"
            stroke="${progressColor}"
            stroke-width="6"
            fill-rule="nonzero"
            stroke-linecap="round"
          ></line>
          <path opacity="0.5" d="M0 10L${innerWidth} 10" stroke="${
            isOverTime ? `url(#paint0_linear)` : 'none'
          }" stroke-width="5" stroke-linecap="round"/>
            <defs>
            <linearGradient id="paint0_linear" x1="0" y1="10" x2="${innerWidth}" y2="10" gradientUnits="userSpaceOnUse">
            <stop stop-color="#B12C09"/>
            <stop offset="1" stop-color='#FF4514'/>
            </linearGradient>
            </defs>
          <use id="use" xlink:href="#tiny-circle" />
        </svg>
      </div>
    </div>
    `}
    </div>
  `;
};

export default class extends SwimlaneElement {
  static get styles() {
    return [super.styles, widgetCss];
  }

  initialize() {
    super.initialize();
    this.innerWidth = 100;
  }

  render() {
    const totalHours = this.record[FIELD1];
    const usedMinutes = this.record[FIELD2];
    return html`
      <div class="slim-widget--container">
        ${template(totalHours, usedMinutes, this.innerWidth)}
      </div>
    `;
  }

  // on resize, get the svg container width
  resizedCallback(entry) {
    this.innerWidth = this.renderRoot.querySelector('.progress-bar--container')
      ? this.renderRoot.querySelector('.progress-bar--container').offsetWidth
      : 100;
    this.requestUpdate();
  }
}

