    button.isActive = true;
    this.requestUpdate();
    this.executeButtonActions(button);
    button.isActive = false;
    this.requestUpdate();
  }

  clickButton(buttonName) {
    const buttons = this.contextData.application.buttons.filter(({name}) => name === buttonName);
    if (buttons){
      for(var i in buttons){
        this.triggerButton(buttons[i].id);
      }
    }
  }

