    this.updateRecordValue('update-current-owner', 'True');
    const timestampString = new Date().toISOString();
    if (!(this.record['time-of-case-assignment'])) {
      this.updateRecordValue('time-of-case-assignment', timestampString); 
    }
    this.updateRecordValue('requires-attention', 'False');
    setTimeout(() => {this.triggerSave()}, 100, this);
    if (button.playbookButtonName){
      this.clickButton(button.playbookButtonName);
    }
  }

}

