          margin-bottom: 6px;
        }

        .proc-list li:last-child {
          margin-bottom: 0;
        }

        .empty {
          color: #909cb4;
          font-size: 12px;
          line-height: 1.45;
          text-align: center;
          padding: 16px 8px;
        }

        .empty-state {
          color: #afb7c8;
          font-size: 13px;
          text-align: center;
          padding: 28px 16px;
          line-height: 1.5;
          position: relative;
          z-index: 0;
        }

        .empty-hint {
          margin-top: 10px;
          font-size: 11px;
          color: #909cb4;
          text-transform: uppercase;
        }
      `
    ];
  }

  constructor() {
    super();
    this.config = { ...baseConfig };
    this._tacticOpen = {};
    this._pickerTacticId = '';
    this._pickerTechId = '';
    this._removeDialogOpen = false;
    this._removeDialogKind = '';
    this._removeDialogMessage = '';
    this._removePendingTacticId = '';
    this._removePendingTechId = '';
    /** @type {AbortController | undefined} */
    this._pickerIsoAbort = undefined;
  }

  connectedCallback() {
    super.connectedCallback();
    this._ensureFullMitreCatalogLoaded();
    this._attachPickerEventIsolation();
  }

  disconnectedCallback() {
    this._detachPickerEventIsolation();
    super.disconnectedCallback();
  }

  _closeOtherPickerSelects(keepOpen) {
    const bar = this._pickerBarElement();
    if (!bar) return;
    for (const sel of bar.querySelectorAll('swim-select')) {
      if (sel === keepOpen || !this._isOpenPickerSelect(sel)) continue;
      const root = sel.shadowRoot;
      const toggle =
        root?.querySelector('.select-input') ?? root?.querySelector('.select-caret');
      if (toggle instanceof HTMLElement) {
        toggle.click();
      }
    }
  }

  _pickerBarElement() {
    return this.renderRoot?.querySelector('.picker-bar') ?? null;
  }

  _isOpenPickerSelect(el) {
    if (!(el instanceof Element) || el.tagName !== 'SWIM-SELECT') return false;
    return el.hasAttribute('open') || el.getAttribute('aria-expanded') === 'true';
  }

  _onPickerSelectOpen(e) {
    this._closeOtherPickerSelects(e.currentTarget);
    this._isolatePickerEvent(e);
  }

  _onPickerSelectClose(e) {
    this._isolatePickerEvent(e);
  }

  /**
   * Record shells sometimes listen on ancestors for `change` / pointer events; `swim-select` uses
   * composed bubbling. Stop propagation at the widget host for anything originating under `.picker-bar`
   * so picking a tactic/technique does not trigger navigation away from the case.
   */
  _attachPickerEventIsolation() {
    if (this._pickerIsoAbort) return;
    this._pickerIsoAbort = new AbortController();
    const { signal } = this._pickerIsoAbort;
    const types = [
      'click',
      'dblclick',
      'mousedown',
      'mouseup',
      'pointerdown',
      'pointerup',
      'change',
      'input'
    ];
    const onPickerBarEvent = e => {
      if (!this._eventPathIncludesPickerBar(e)) return;
      e.stopPropagation();
      if (e.type === 'change' || e.type === 'input') {
        e.stopImmediatePropagation?.();
      }
    };
    for (const t of types) {
      this.addEventListener(t, onPickerBarEvent, { signal });
    }
  }

  _detachPickerEventIsolation() {
    this._pickerIsoAbort?.abort();
    this._pickerIsoAbort = undefined;
  }

  _eventPathIncludesPickerBar(e) {
    const path = typeof e.composedPath === 'function' ? e.composedPath() : [];
    for (let i = 0; i < path.length; i++) {
      const n = path[i];
      if (n instanceof Element && n.classList?.contains('picker-bar')) return true;
    }
    return false;
  }

  /** Full MITRE enterprise catalog (shared). Null until first successful fetch or if disabled / failed. */
  static get _mitreEnterpriseCatalog() {
    return MitreAttackTtp.__mitreCatalog;
  }

  static set _mitreEnterpriseCatalog(v) {
    MitreAttackTtp.__mitreCatalog = v;
  }

  static get _mitreCatalogFetchPromise() {
    return MitreAttackTtp.__mitreFetchPromise;
  }

  static set _mitreCatalogFetchPromise(v) {
    MitreAttackTtp.__mitreFetchPromise = v;
  }

  _getAttackCatalog() {
    if (this.config?.loadFullMitreCatalog === false) return EMBEDDED_FALLBACK_CATALOG;
    return MitreAttackTtp._mitreEnterpriseCatalog || EMBEDDED_FALLBACK_CATALOG;
  }

  _mitreCatalogLoading() {
    if (this.config?.loadFullMitreCatalog === false) return false;
    return MitreAttackTtp._mitreCatalogFetchPromise != null;
  }

  _mitreCatalogFetchFailed() {
    if (this.config?.loadFullMitreCatalog === false) return false;
    return (
      MitreAttackTtp.__mitreFetchSettled &&
      MitreAttackTtp._mitreEnterpriseCatalog == null
    );
  }

  _ensureFullMitreCatalogLoaded() {
    if (this.config?.loadFullMitreCatalog === false) return;

    if (MitreAttackTtp._mitreEnterpriseCatalog) return;

    if (MitreAttackTtp._mitreCatalogFetchPromise) {
      MitreAttackTtp._mitreCatalogFetchPromise
        .then(() => this.requestUpdate())
        .catch(() => this.requestUpdate());
      return;
    }

    const url = this.config?.mitreStixJsonUrl || DEFAULT_MITRE_STIX_JSON_URL;

    const cachedTactics = readMitreCatalogFromSessionStorage(url);
    if (cachedTactics && cachedTactics.length > 0) {
      MitreAttackTtp._mitreEnterpriseCatalog = cachedTactics;
      MitreAttackTtp.__mitreFetchSettled = true;
      this.requestUpdate();
      return;
    }

    MitreAttackTtp._mitreCatalogFetchPromise = fetch(url, { credentials: 'omit' })
      .then(r => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json();
      })
      .then(bundle => {
        const tactics = parseEnterpriseAttackToTactics(bundle);
        if (tactics.length) {
          writeMitreCatalogToSessionStorage(url, tactics);
        }
        MitreAttackTtp._mitreEnterpriseCatalog = tactics.length ? tactics : null;
        if (!tactics.length) {
          console.warn('mitre-attack-ttp: parsed zero tactics from STIX bundle — check URL / format');
        }
      })
      .catch(err => {
        console.warn('mitre-attack-ttp: MITRE STIX load failed', err);
        MitreAttackTtp._mitreEnterpriseCatalog = null;
      })
      .finally(() => {
        MitreAttackTtp.__mitreFetchSettled = true;
        MitreAttackTtp._mitreCatalogFetchPromise = null;
        this.requestUpdate();
      });
  }

  setConfig(userConfig, replaceAll = false) {
    this.config = replaceAll ? { ...baseConfig, ...userConfig } : { ...this.config, ...userConfig };
    this.requestUpdate();
  }

  willUpdate(changed) {
    super.willUpdate(changed);
    if (
      changed.has('record') ||
      changed.has('config') ||
      changed.has('contextData') ||
      changed.has('data')
    ) {
      const { tactics } = this._getTactics();
      const valid = new Set(tactics.map((t, i) => this._tacticKey(t, i)));
      const next = {};
      for (const k of Object.keys(this._tacticOpen)) {
        if (valid.has(k)) next[k] = this._tacticOpen[k];
      }
      this._tacticOpen = next;
    }
  }

  _tacticKey(tactic, index) {
    return String(tactic.id || tactic.name || index);
  }

  _panelDomId(key) {
    return `ttp-${String(key).replace(/[^a-zA-Z0-9_-]/g, '-')}`;
  }

  /** Explicit toggle in _tacticOpen; otherwise only the first tactic column starts expanded. */
  _isTacticOpen(key, index) {
    if (Object.prototype.hasOwnProperty.call(this._tacticOpen, key)) {
      return this._tacticOpen[key];
    }
    return index === 0;
  }

  _toggleTactic(key, index) {
    const cur = this._isTacticOpen(key, index);
    this._tacticOpen = { ...this._tacticOpen, [key]: !cur };
  }

  /**
   * Record object used for field read/write. Walks `this.record` → `data.record` → `contextData.record` →
   * `case.record` and returns the **first** object that already holds the MITRE field (built-in keys or
   * custom `recordFieldKey`), so an empty stub `this.record` does not hide populated `contextData.record`.
   */
  _getRecord() {
    const ctx = this.contextData ?? this['context-data'];
    const chain = [this.record, this.data?.record, ctx?.record, ctx?.case?.record].filter(
      r => r != null && typeof r === 'object'
    );
    if (chain.length === 0) return null;

    const cfgRaw = this.config?.recordFieldKey;
    const cfg = cfgRaw != null && String(cfgRaw).trim() !== '' ? String(cfgRaw).trim() : null;
    const keysProbe =
      cfg && !MITRE_FIELD_KEYS_TO_TRY.includes(cfg) ? [cfg] : MITRE_FIELD_KEYS_TO_TRY;

    for (const rec of chain) {
      for (const k of keysProbe) {
        const v = readRecordFieldRawFromRecordObject(rec, k);
        if (v !== undefined && v !== null) return rec;
      }
    }
    return chain[0];
  }

  /**
   * Field key for MITRE TTP read/write.
   * - Custom key: `config.recordFieldKey` when set to a value **not** in the built-in singular/plural pair.
   * - Otherwise: first built-in key that already has data on the record, else `DEFAULT_FIELD_KEY`.
   * (Never trust a default `recordFieldKey` in config alone — it must not skip record detection.)
   */
  _getMitreFieldKey() {
    const cfgRaw = this.config?.recordFieldKey;
    const cfg = cfgRaw != null && String(cfgRaw).trim() !== '' ? String(cfgRaw).trim() : null;

    if (cfg && !MITRE_FIELD_KEYS_TO_TRY.includes(cfg)) {
      return cfg;
    }

    const rec = this._getRecord();
    if (rec) {
      for (const k of MITRE_FIELD_KEYS_TO_TRY) {
        const v = readRecordFieldRawFromRecordObject(rec, k);
        if (v !== undefined && v !== null) return k;
      }
    }

    if (cfg) return cfg;
    return DEFAULT_FIELD_KEY;
  }

  /** Raw field payload from Turbine (`record[key]`, `record.values[key]`, or `record.fields[key]`). */
  _readRecordFieldRaw(key) {
    return readRecordFieldRawFromRecordObject(this._getRecord(), key);
  }

  _parseField(raw) {
    return parseMitreFieldRaw(raw, this._getAttackCatalog());
  }

  /** Matches `recordDataShape` / `auto` detection for persistence. */
  _resolvePersistDataShape() {
    const explicit = this.config?.recordDataShape ?? 'auto';
    if (
      explicit === 'canonical' ||
      explicit === 'alert_mitre_array' ||
      explicit === 'mitre_name_lines' ||
      explicit === 'swimlane_string_list'
    ) {
      return explicit;
    }
    const key = this._getMitreFieldKey();
    const cat = this._getAttackCatalog();
    let raw = unwrapRecordField(this._readRecordFieldRaw(key));
    if (raw == null || raw === '') {
      if (String(key).toLowerCase().includes('alert_mitre')) return 'alert_mitre_array';
      if (String(key).toLowerCase().includes('mitre-attack-technique')) return 'swimlane_string_list';
      return 'canonical';
    }
    if (typeof raw === 'string' && isMitreNameLinesString(raw)) return 'mitre_name_lines';
    let data = raw;
    if (typeof raw === 'string') {
      try {
        data = JSON.parse(raw);
      } catch {
        return 'canonical';
      }
    }
    if (Array.isArray(data) && data.length > 0 && isSwimlaneMitrePlainStringArray(data)) {
      return 'swimlane_string_list';
    }
    if (Array.isArray(data) && data.length > 0 && isSwimlaneStringListItemArray(data)) {
      return 'swimlane_string_list';
    }
    if (Array.isArray(data) && data.length > 0 && isAlertMitreTacticTechniqueRow(data[0])) {
      return 'alert_mitre_array';
    }
    if (typeof data === 'object' && data != null && !Array.isArray(data)) {
      const parsed = parseFieldJsonPayload(data, cat);
      if (
        (parsed.length === 0 || tacticsLookLikeEmptyShellColumns(parsed)) &&
        gatherMitreNameLineStringsFromObject(data).length > 0
      ) {
        return 'mitre_name_lines';
      }
    }
    return 'canonical';
  }

  _buildPersistValue(orderedTactics) {
    const shape = this._resolvePersistDataShape();
    const fieldKey = this._getMitreFieldKey();
    const jsonStr = Boolean(this.config?.persistFieldAsJsonString);

    if (shape === 'mitre_name_lines') {
      return tacticsToMitreNameLinesString(orderedTactics);
    }

    if (shape === 'swimlane_string_list') {
      if (this.config?.mitreSwimlaneSaveAsListObjects === true) {
        let prev = unwrapRecordField(this._readRecordFieldRaw(fieldKey));
        if (typeof prev === 'string') {
          try {
            prev = JSON.parse(prev);
          } catch {
            prev = [];
          }
        }
        return tacticsToSwimlaneStringListItems(
          orderedTactics,
          Array.isArray(prev) ? prev : []
        );
      }
      return tacticsToSwimlaneStringListPlainStrings(orderedTactics);
    }

    const payload =
      shape === 'alert_mitre_array'
        ? tacticsToAlertMitreArray(orderedTactics)
        : { tactics: orderedTactics };
    return jsonStr ? JSON.stringify(payload) : payload;
  }

  /** Tactics currently stored on the record. */
  _getPersistedTacticsClone() {
    const key = this._getMitreFieldKey();
    const raw = this._readRecordFieldRaw(key);
    return sortTacticsByCatalogOrder(cloneTacticsList(this._parseField(raw)), this._getAttackCatalog());
  }

  /** True if this technique id is already under the given tactic column on the record. */
  _techniqueAlreadyOnRecord(techId, tacticId) {
    if (!techId || !tacticId) return false;
    const tac = this._getPersistedTacticsClone().find(t => t.id === tacticId);
    return Boolean(tac?.techniques?.some(tech => tech.id === techId));
  }

  _tacticPickerOptions() {
    const cat = this._getAttackCatalog();
    return cat.map(t => ({
      name: `${t.id} — ${t.name}`,
      value: t.id
    }));
  }

  _techniquePickerOptions() {
    const tactic = this._getAttackCatalog().find(t => t.id === this._pickerTacticId);
    if (!tactic) return [];
    return (tactic.techniques || []).map(tech => {
      const onCase = this._techniqueAlreadyOnRecord(tech.id, this._pickerTacticId);
      return {
        name: `${tech.id} — ${tech.name}${onCase ? ' — on case' : ''}`,
        value: tech.id
      };
    });
  }

  _getPickerSelectMaxWidth() {
    const raw = this.config?.pickerSelectMaxWidth;
    if (raw == null || raw === '') return DEFAULT_PICKER_SELECT_MAX_WIDTH;
    const n = Number(raw);
    if (Number.isFinite(n) && n >= 180) return Math.round(n);
    return DEFAULT_PICKER_SELECT_MAX_WIDTH;
  }

  _pickerBarStyle() {
    return `--picker-select-max-width: ${this._getPickerSelectMaxWidth()}px`;
  }

  _pickerTacticDisplayLabel() {
    if (!this._pickerTacticId) return '';
    const opt = this._tacticPickerOptions().find(o => String(o.value) === this._pickerTacticId);
    return opt?.name ?? this._pickerTacticId;
  }

  _pickerTechniqueDisplayLabel() {
    if (!this._pickerTacticId || !this._pickerTechId) return '';
    const opt = this._techniquePickerOptions().find(o => String(o.value) === this._pickerTechId);
    return opt?.name ?? this._pickerTechId;
  }

  _renderPickerSelectionPreview() {
    const tacticLabel = this._pickerTacticDisplayLabel();
    const techniqueLabel = this._pickerTechniqueDisplayLabel();
    if (!tacticLabel && !techniqueLabel) return html``;

    return html`
      <div class="picker-selection-preview" aria-live="polite">
        ${tacticLabel
          ? html`<p class="picker-preview-row">
              <span class="picker-preview-label">Tactic</span>${tacticLabel}
            </p>`
          : null}
        ${techniqueLabel
          ? html`<p class="picker-preview-row">
              <span class="picker-preview-label">Technique</span>${techniqueLabel}
            </p>`
          : null}
      </div>
    `;
  }

  /**
   * Stop Turbine record shells from reacting to bubbled picker events. Do not use
   * stopImmediatePropagation on pointer/click — it can block swim-select handlers on the technique control.
   */
  _isolatePickerEvent(e) {
    e?.stopPropagation?.();
  }

  _isolatePickerChangeEvent(e) {
    this._isolatePickerEvent(e);
    e?.stopImmediatePropagation?.();
  }

  _onTacticPickerChange(e) {
    this._isolatePickerChangeEvent(e);
    const v = e.detail?.value;
    this._pickerTacticId = v ? String(v) : '';
    this._pickerTechId = '';
  }

  _onTechniquePickerChange(e) {
    this._isolatePickerChangeEvent(e);
    const v = e.detail?.value;
    this._pickerTechId = v ? String(v) : '';
  }

  /**
   * Resolves Turbine field id for `setValue` when key-based lookup in the shell is incomplete.
   */
  _resolvePersistFieldId(fieldKey) {
    const cfgId = this.config?.recordFieldId;
    if (cfgId != null && String(cfgId).trim() !== '') {
      return String(cfgId).trim();
    }
    const keysToMatch = [fieldKey, ...MITRE_FIELD_KEYS_TO_TRY.filter(k => k !== fieldKey)];
    if (typeof this.getFieldId === 'function') {
      for (const k of keysToMatch) {
        try {
          const id = this.getFieldId(k);
          if (id != null && String(id).trim() !== '') return String(id).trim();
        } catch {
          /* key missing in context */
        }
      }
    }
    const ctx = this.contextData ?? this['context-data'];
    const lists = [ctx?.application?.fields, ctx?.app?.fields];
    for (const list of lists) {
      if (!Array.isArray(list)) continue;
      for (const k of keysToMatch) {
        const f = list.find(x => x && x.key === k);
        if (f?.id != null && String(f.id).trim() !== '') return String(f.id).trim();
      }
    }
    return undefined;
  }

  /**
   * Dispatches `action` / `setValue` the way Turbine expects, including `fieldId` when the key is not in
   * `contextData.application.fields` (avoids host `field` undefined → `reading 'id'`).
   */
  _setMitreTtpRecordValue(fieldKey, value) {
    const fieldId = this._resolvePersistFieldId(fieldKey);
    if (fieldId) {
      const detail = {
        actionType: 'setValue',
        key: fieldKey,
        fieldId,
        value
      };
      const opts = { detail, bubbles: true, composed: true, cancelable: true };
      this.dispatchEvent(new CustomEvent('action', opts));
      const host = typeof this.closest === 'function' ? this.closest('widget-element') : null;
      if (host && host !== this) {
        host.dispatchEvent(new CustomEvent('action', opts));
      }
      return;
    }
    try {
      super.updateRecordValue(fieldKey, value);
    } catch (e) {
      console.warn(
        'mitre-attack-ttp: updateRecordValue failed; set widget config recordFieldId to the field UUID (Application → Fields).',
        e
      );
    }
  }

  _mitrePersistHint(fieldKey) {
    const rec = this._getRecord();
    if (!rec || rec.id == null || rec.id === '') {
      console.warn(
        'mitre-attack-ttp: record.id is missing; if Add to case does nothing or errors, save the record first.'
      );
    }
    if (this._resolvePersistFieldId(fieldKey)) return;

    const keysToCheck = [fieldKey, ...MITRE_FIELD_KEYS_TO_TRY.filter(k => k !== fieldKey)];
    const ctx = this.contextData ?? this['context-data'];
    const fields = ctx?.application?.fields;
    if (
      Array.isArray(fields) &&
      fields.length > 0 &&
      !keysToCheck.some(k => fields.some(f => f && f.key === k))
    ) {
      console.warn(
        `mitre-attack-ttp: none of [${keysToCheck.map(k => `"${k}"`).join(', ')}] appear in context fields and no recordFieldId / getFieldId match — set widget config recordFieldId to the field UUID (Application → Fields).`
      );
    }
  }

  _addSelectedTechnique(e) {
    if (e && typeof e.stopPropagation === 'function') {
      e.stopPropagation();
      if (typeof e.stopImmediatePropagation === 'function') e.stopImmediatePropagation();
      e.preventDefault?.();
    }
    const tacticId = this._pickerTacticId;
    const techId = this._pickerTechId;
    if (!tacticId || !techId || this._techniqueAlreadyOnRecord(techId, tacticId)) return;

    const fieldKey = this._getMitreFieldKey();

    const cat = this._getAttackCatalog();
    const catalogTactic = cat.find(t => t.id === tacticId);
    const catalogTech = catalogTactic?.techniques?.find(t => t.id === techId);
    if (!catalogTactic || !catalogTech) {
      console.warn(
        'mitre-attack-ttp: Add to case skipped — tactic/technique not in loaded catalog (wait for STIX load or enable loadFullMitreCatalog).'
      );
      return;
    }

    const tactics = this._getPersistedTacticsClone();
    let tacticEntry = tactics.find(t => t.id === tacticId);
    if (!tacticEntry) {
      tacticEntry = {
        id: catalogTactic.id,
        name: catalogTactic.name,
        techniques: []
      };
      tactics.push(tacticEntry);
    }
    if (tacticEntry.techniques.some(t => t.id === techId)) return;

    const added = normalizeTechniqueShape({
      id: catalogTech.id,
      name: catalogTech.name,
      procedures: catalogTech.procedures
    });
    if (added) tacticEntry.techniques.push(added);
    tacticEntry.techniques = sortTechniquesForTactic(tacticId, tacticEntry.techniques, cat);

    const ordered = sortTacticsByCatalogOrder(tactics, cat);
    const value = this._buildPersistValue(ordered);

    this._mitrePersistHint(fieldKey);
    this._setMitreTtpRecordValue(fieldKey, value);
    this._pickerTechId = '';
    this._tacticOpen = { ...this._tacticOpen, [tacticId]: true };
    this.requestUpdate();
  }

  _addButtonDisabled() {
    return (
      !this._pickerTacticId ||
      !this._pickerTechId ||
      this._techniqueAlreadyOnRecord(this._pickerTechId, this._pickerTacticId)
    );
  }

  /** Tactic + technique chosen but that pair is not on the record — block Remove to avoid clearing the case by mistake. */
  _pickerBlocksRemoveBecauseNewPair() {
    const tac = this._pickerTacticId;
    const tech = this._pickerTechId;
    if (!tac || !tech) return false;
    return !this._techniqueAlreadyOnRecord(tech, tac);
  }

  _removeButtonDisabled() {
    if (!this._hasPersistedTtpData()) return true;
    if (this._pickerBlocksRemoveBecauseNewPair()) return true;
    return false;
  }

  /** Non-empty tactics parsed from the record field (not the live catalog). */
  _hasPersistedTtpData() {
    const key = this._getMitreFieldKey();
    return this._parseField(this._readRecordFieldRaw(key)).length > 0;
  }

  _persistEmptyTacticsToRecord() {
    const fieldKey = this._getMitreFieldKey();
    const shape = this._resolvePersistDataShape();
    let value;
    if (shape === 'mitre_name_lines') {
      value = '';
    } else if (shape === 'swimlane_string_list') {
      value = [];
    } else {
      const payload = shape === 'alert_mitre_array' ? [] : { tactics: [] };
      value = this.config?.persistFieldAsJsonString ? JSON.stringify(payload) : payload;
    }
    this._mitrePersistHint(fieldKey);
    this._setMitreTtpRecordValue(fieldKey, value);
  }

  _useSwimRemoveConfirm() {
    return this.config?.removeConfirmPresentation === 'dialog';
  }

  _openRemoveConfirmDialog(kind, message, tacticId, techId) {
    this._removeDialogKind = kind;
    this._removeDialogMessage = message;
    this._removePendingTacticId = tacticId || '';
    this._removePendingTechId = techId || '';
    this._removeDialogOpen = true;
  }

  _resetRemoveDialogState() {
    this._removeDialogOpen = false;
    this._removeDialogKind = '';
    this._removeDialogMessage = '';
    this._removePendingTacticId = '';
    this._removePendingTechId = '';
  }

  _onRemoveDialogClose() {
    this._resetRemoveDialogState();
  }

  _onRemoveDialogCancel(e) {
    e?.stopPropagation?.();
    e?.preventDefault?.();
    this._resetRemoveDialogState();
    this.requestUpdate();
  }

  _onRemoveDialogConfirm(e) {
    e?.stopPropagation?.();
    e?.preventDefault?.();
    const kind = this._removeDialogKind;
    const tacticId = this._removePendingTacticId;
    const techId = this._removePendingTechId;
    this._resetRemoveDialogState();
    if (kind === 'single') {
      this._persistRemoveSelectedTechnique(tacticId, techId);
      this._pickerTechId = '';
    } else if (kind === 'clear') {
      this._persistEmptyTacticsToRecord();
      this._tacticOpen = {};
    }
    this.requestUpdate();
  }

  _removeTtpFromCase(e) {
    if (e && typeof e.stopPropagation === 'function') {
      e.stopPropagation();
      if (typeof e.stopImmediatePropagation === 'function') e.stopImmediatePropagation();
      e.preventDefault?.();
    }
    if (this._removeButtonDisabled()) return;

    const tacticId = this._pickerTacticId;
    const techId = this._pickerTechId;
    const removeSelectedOnly =
      tacticId && techId && this._techniqueAlreadyOnRecord(techId, tacticId);
    const needConfirm = this.config?.confirmRemoveFromCase !== false;
    const swimConfirm = needConfirm && this._useSwimRemoveConfirm();

    if (removeSelectedOnly) {
      if (needConfirm) {
        const cat = this._getAttackCatalog();
        const tacName =
          cat.find(t => t.id === tacticId)?.name || tacticId;
        const techName =
          cat.find(t => t.id === tacticId)?.techniques?.find(x => x.id === techId)?.name || techId;
        const msg = `Remove “${techName}” under “${tacName}” from this case?`;
        if (swimConfirm) {
          this._openRemoveConfirmDialog('single', msg, tacticId, techId);
          return;
        }
        if (
          typeof window !== 'undefined' &&
          window.confirm &&
          !window.confirm(msg)
        ) {
          return;
        }
      }
      this._persistRemoveSelectedTechnique(tacticId, techId);
      this._pickerTechId = '';
      this.requestUpdate();
      return;
    }

    if (needConfirm) {
      const msg =
        'Remove all MITRE ATT&CK TTPs from this case? Saved tactics and techniques on the record will be cleared.';
      if (swimConfirm) {
        this._openRemoveConfirmDialog('clear', msg, '', '');
        return;
      }
      if (
        typeof window !== 'undefined' &&
        window.confirm &&
        !window.confirm(msg)
      ) {
        return;
      }
    }
    this._persistEmptyTacticsToRecord();
    this._tacticOpen = {};
    this.requestUpdate();
  }

  /** True if this tactic column is on the record (match by id, else name). */
  _tacticOnRecord(tactic) {
    if (!tactic || typeof tactic !== 'object') return false;
    const tactics = this._getPersistedTacticsClone();
    if (tactic.id) return tactics.some(t => t.id === tactic.id);
    if (tactic.name) return tactics.some(t => !t.id && t.name === tactic.name);
    return false;
  }

  /** Drop an entire tactic column and all techniques under it; clear field if nothing left. */
  _persistRemoveTactic(tactic) {
    if (!this._tacticOnRecord(tactic)) return;
    const fieldKey = this._getMitreFieldKey();
    const tactics = this._getPersistedTacticsClone();
    const remaining = tactics.filter(t => {
      if (tactic.id) return t.id !== tactic.id;
      if (tactic.name) return !(t.name === tactic.name && !t.id);
      return true;
    });
    if (remaining.length === 0) {
      this._persistEmptyTacticsToRecord();
      this._tacticOpen = {};
      return;
    }
    const cat = this._getAttackCatalog();
    const ordered = sortTacticsByCatalogOrder(remaining, cat);
    const value = this._buildPersistValue(ordered);
    this._mitrePersistHint(fieldKey);
    this._setMitreTtpRecordValue(fieldKey, value);
  }

  /** Remove entire tactic column from the board (immediate — no confirm). */
  _removeTacticFromColumn(e, tactic) {
    if (e && typeof e.stopPropagation === 'function') {
      e.stopPropagation();
      if (typeof e.stopImmediatePropagation === 'function') e.stopImmediatePropagation();
      e.preventDefault?.();
    }
    if (!tactic || !this._tacticOnRecord(tactic)) return;
    this._persistRemoveTactic(tactic);
    if (tactic.id && this._pickerTacticId === tactic.id) {
      this._pickerTacticId = '';
      this._pickerTechId = '';
    }
    this.requestUpdate();
  }

  /** Drop one technique under one tactic column; clear field if nothing left. */
  _persistRemoveSelectedTechnique(tacticId, techId) {
    const fieldKey = this._getMitreFieldKey();
    const tactics = this._getPersistedTacticsClone();
    const tac = tactics.find(t => t.id === tacticId);
    if (!tac) return;
    tac.techniques = (tac.techniques || []).filter(t => t.id !== techId);
    const remaining = tactics.filter(t => (t.techniques || []).length > 0);
    if (remaining.length === 0) {
      this._persistEmptyTacticsToRecord();
      this._tacticOpen = {};
      return;
    }
    const cat = this._getAttackCatalog();
    const ordered = sortTacticsByCatalogOrder(remaining, cat);
    const value = this._buildPersistValue(ordered);
    this._mitrePersistHint(fieldKey);
    this._setMitreTtpRecordValue(fieldKey, value);
  }

  /** Remove one technique from its card (immediate — no confirm). */
  _removeTechniqueFromCard(e, tacticId, techId) {
    if (e && typeof e.stopPropagation === 'function') {
      e.stopPropagation();
      if (typeof e.stopImmediatePropagation === 'function') e.stopImmediatePropagation();
      e.preventDefault?.();
    }
    if (!tacticId || !techId) return;
    if (!this._techniqueAlreadyOnRecord(techId, tacticId)) return;
    this._persistRemoveSelectedTechnique(tacticId, techId);
    if (this._pickerTacticId === tacticId && this._pickerTechId === techId) {
      this._pickerTechId = '';
    }
    this.requestUpdate();
  }

  _renderPicker() {
    const loading = this._mitreCatalogLoading();
    const failedFull = this._mitreCatalogFetchFailed();
    const tacticOptions = this._tacticPickerOptions();
    const techniqueOptions = this._techniquePickerOptions();
    const tacticChosen = Boolean(this._pickerTacticId);
    const pickerLocked = loading;

    return html`
      <div
        class="picker-bar"
        part="picker-bar"
        style=${this._pickerBarStyle()}
        @click=${e => this._isolatePickerEvent(e)}
        @mousedown=${e => this._isolatePickerEvent(e)}
        @mouseup=${e => this._isolatePickerEvent(e)}
        @pointerdown=${e => this._isolatePickerEvent(e)}
        @pointerup=${e => this._isolatePickerEvent(e)}
      >
        ${loading
          ? html`<span class="picker-status picker-status--loading"
              >Loading MITRE ATT&CK enterprise catalog (full technique list)…</span
            >`
          : failedFull
            ? html`<span class="picker-status picker-status--warn"
                >Full catalog could not be loaded. Picker catalog is empty until the fetch succeeds — check network,
                CORS, or <code>mitreStixJsonUrl</code>.</span
              >`
            : null}
        <swim-select
          ?marginless=${true}
          label="Tactic"
          placeholder=${pickerLocked ? 'Loading…' : 'Select tactic'}
          filterable
          ?disabled=${pickerLocked}
          .options=${tacticOptions}
          .value=${this._pickerTacticId || null}
          @change=${e => this._onTacticPickerChange(e)}
          @open=${e => this._onPickerSelectOpen(e)}
          @close=${e => this._onPickerSelectClose(e)}
        ></swim-select>
        <swim-select
          ?marginless=${true}
          label="Technique"
          placeholder=${pickerLocked
            ? 'Loading…'
            : tacticChosen
              ? 'Select technique'
              : 'Select a tactic first'}
          filterable
          ?disabled=${pickerLocked || !tacticChosen}
          empty-placeholder="No techniques"
          .options=${techniqueOptions}
          .value=${this._pickerTechId || null}
          @change=${e => this._onTechniquePickerChange(e)}
          @open=${e => this._onPickerSelectOpen(e)}
          @close=${e => this._onPickerSelectClose(e)}
        ></swim-select>
        <div class="picker-actions">
          <swim-button
            variant="primary"
            type="button"
            ?disabled=${pickerLocked || this._addButtonDisabled()}
            @click=${e => this._addSelectedTechnique(e)}
          >
            Add to case
          </swim-button>
          <swim-button
            variant="bordered"
            type="button"
            ?disabled=${this._removeButtonDisabled()}
            @click=${e => this._removeTtpFromCase(e)}
          >
            Remove from case
          </swim-button>
        </div>
        ${this._renderPickerSelectionPreview()}
      </div>
    `;
  }

  _renderRemoveConfirmDialog() {
    return html`
      <swim-dialog
        format="regular"
        .closeButton=${false}
        .visible=${this._removeDialogOpen}
        .zIndex=${2400}
        @close=${this._onRemoveDialogClose}
      >
        <div class="remove-dialog-panel">
          <div class="remove-dialog-header">
            <h2 class="remove-dialog-title">Remove from case</h2>
            <button
              type="button"
              class="remove-dialog-close"
              aria-label="Close dialog"
              @click=${this._onRemoveDialogCancel}
            >
              <swim-icon font-icon="x" icon-class="ngx-icon ngx-x"></swim-icon>
            </button>
          </div>
          <p class="remove-dialog-message">${this._removeDialogMessage}</p>
          <div class="remove-dialog-actions">
            <swim-button variant="bordered" type="button" @click=${this._onRemoveDialogCancel}>
              Cancel
            </swim-button>
            <swim-button
              class="remove-confirm-btn"
              variant="default"
              type="button"
              @click=${this._onRemoveDialogConfirm}
            >
              Remove
            </swim-button>
          </div>
        </div>
      </swim-dialog>
    `;
  }

  _getTactics() {
    const key = this._getMitreFieldKey();
    const fromRecord = this._parseField(this._readRecordFieldRaw(key));
    const tactics = enrichTacticsProceduresFromCatalog(fromRecord, this._getAttackCatalog());
    if (tactics.length > 0) {
      return { tactics };
    }
    return { tactics: [] };
  }

  _renderMitreIdLink(id, kind, spanClass) {
    const sid = String(id ?? '').trim();
    if (!sid) return null;
    const url = resolveMitreAttackUrl(sid, this._getAttackCatalog(), kind);
    if (!url) return html`<span class=${spanClass}>${sid}</span>`;
    return html`
      <a
        class="mitre-id-link ${spanClass}"
        href=${url}
        target="_blank"
        rel="noopener noreferrer"
        aria-label=${`Open ${sid} on MITRE ATT&CK`}
        @click=${e => e.stopPropagation()}
      >${sid}</a>
    `;
  }

  _renderTechnique(tech, tacticId) {
    const t = normalizeTechniqueShape(tech);
    if (!t) return html``;
    const removeLabel = `Remove ${t.name} from case`;
    return html`
      <article class="technique-card" aria-label=${t.name}>
        <div class="technique-card-header">
          <div class="tech-line">
            ${t.id ? this._renderMitreIdLink(t.id, 'technique', 'tech-id') : null}
            <span class="tech-name">${t.name}</span>
          </div>
          ${t.id && tacticId
            ? html`
                <button
                  type="button"
                  class="technique-card-remove"
                  aria-label=${removeLabel}
                  title=${removeLabel}
                  @click=${e => this._removeTechniqueFromCard(e, tacticId, t.id)}
                >
                  <swim-icon font-icon="trash" alt="Remove from case"></swim-icon>
                </button>
              `
            : null}
        </div>
        ${t.procedures.length
          ? html`
              <div class="proc-label">Procedures observed</div>
              <ul class="proc-list">
                ${repeat(t.procedures, (p, i) => `${i}-${String(p).slice(0, 24)}`, p => html`<li>${p}</li>`)}
              </ul>
            `
          : null}
      </article>
    `;
  }

  _renderTactic(tactic, index) {
    const key = this._tacticKey(tactic, index);
    const open = this._isTacticOpen(key, index);
    const techniques = Array.isArray(tactic.techniques) ? tactic.techniques : [];

    const tacticRemoveLabel = `Remove ${tactic.name || tactic.id || 'tactic'} and all techniques from case`;

    return html`
      <div class="tactic-column" role="presentation">
        <div class="tactic-header-row">
          <div class="tactic-header-main">
            <button
              type="button"
              class="tactic-header-toggle"
              aria-expanded=${open ? 'true' : 'false'}
              aria-controls=${this._panelDomId(key)}
              @click=${e => {
                e.stopPropagation();
                if (typeof e.stopImmediatePropagation === 'function') e.stopImmediatePropagation();
                this._toggleTactic(key, index);
              }}
            >
              ${chevronSvg(open)}
              <span class="tactic-header-text">
                ${tactic.id ? this._renderMitreIdLink(tactic.id, 'tactic', 'tactic-header-id') : null}
                <span class="tactic-header-name">${tactic.name || 'Tactic'}</span>
              </span>
            </button>
          </div>
          <button
            type="button"
            class="tactic-column-remove"
            aria-label=${tacticRemoveLabel}
            title=${tacticRemoveLabel}
            @click=${e => this._removeTacticFromColumn(e, tactic)}
          >
            <swim-icon font-icon="trash" alt="Remove tactic from case"></swim-icon>
          </button>
        </div>
        ${open
          ? html`
              <div
                class="tactic-body"
                id=${this._panelDomId(key)}
                role="region"
                aria-label=${`${tactic.name || tactic.id || 'Tactic'} techniques`}
              >
                ${techniques.length === 0
                  ? html`<div class="empty">No techniques under this tactic.</div>`
                    : repeat(
                      techniques,
                      (t, i) => t?.id ?? `tech-${i}`,
                      t => this._renderTechnique(t, tactic.id)
                    )}
              </div>
            `
          : null}
      </div>
    `;
  }

  render() {
    const { tactics } = this._getTactics();

    return recordFrameTemplate(html`
      <div class="shell">
        <div class="shell-banner"></div>
        ${this._renderPicker()}
        ${this._renderRemoveConfirmDialog()}
        ${tactics.length === 0
          ? html`
              <div class="empty-state">
                No MITRE ATT&CK TTPs are stored on this record.
                <div class="empty-hint">
                  Use the tactic and technique dropdowns above, or populate “${this._getMitreFieldKey()}” with JSON,
                  a Swimlane string list, or multiline <code>Tactic / Technique</code> text (see README).
                </div>
              </div>
            `
          : html`
              <div class="tactics-row">
                ${repeat(tactics, (t, i) => this._tacticKey(t, i), (t, i) => this._renderTactic(t, i))}
              </div>
            `}
      </div>
    `);
  }
}

MitreAttackTtp.__mitreCatalog = null;
MitreAttackTtp.__mitreFetchPromise = null;
MitreAttackTtp.__mitreFetchSettled = false;

