export class SwimlaneTimelineList extends SwimlaneElement {
  constructor(...args) {
    super(...args);
    this.data = [];
    this._processedData = [];
    this._highlightedIndex = -1;
  }

  static get properties() {
    return {
      data: { type: Array },
      _highlightedIndex: { type: Number, state: true },
    };
  }

  static get styles() {
    return [super.styles, widgetCss];
  }

  updated(changedProps) {
    if (changedProps.has('data')) {
      this._processData();
    }
  }

  _processData() {
    if (!this.data || this.data.length === 0) {
      this._processedData = [];
      return;
    }

    // Sort data by timestamp (oldest first - chronological order)
    const sorted = [...this.data].sort((a, b) => {
      const dateA = new Date(a.timestamp);
      const dateB = new Date(b.timestamp);
      return dateA - dateB; // Ascending - chronological
    });

    // Get time range (for timeline positioning)
    const times = this.data.map(d => new Date(d.timestamp).getTime());
    const minTime = Math.min(...times);
    const maxTime = Math.max(...times);
    const timeRange = maxTime - minTime || 1;

    // Group events by date and calculate timeline positions
    const dateGroups = new Map();

    sorted.forEach((item, index) => {
      const date = new Date(item.timestamp);
      const dateKey = date.toLocaleDateString('en-US', {
        weekday: 'short',
        month: 'short',
        day: 'numeric'
      });

      const time = date.getTime();
      const xPercent = ((time - minTime) / timeRange) * 100;

      const processedItem = {
        ...item,
        xPercent,
        time,
        listIndex: index,
        formattedTime: this._formatTime(item.timestamp),
        formattedSource: this._formatSource(item.added_by, item.playbook_name),
      };

      if (!dateGroups.has(dateKey)) {
        dateGroups.set(dateKey, []);
      }
      dateGroups.get(dateKey).push(processedItem);
    });

    this._processedData = sorted.map((item, index) => {
      const date = new Date(item.timestamp);
      const time = date.getTime();
      const xPercent = ((time - minTime) / timeRange) * 100;

      return {
        ...item,
        xPercent,
        time,
        listIndex: index,
        formattedTime: this._formatTime(item.timestamp),
        formattedSource: this._formatSource(item.added_by, item.playbook_name),
      };
    });

    this._dateGroups = dateGroups;
    this._minTime = minTime;
    this._maxTime = maxTime;
    this.requestUpdate();
  }

  _formatSource(addedBy, playbook_name) {
    if (addedBy && playbook_name) {
      return `Added by ${addedBy} via ${playbook_name}`;
    } else if (playbook_name) {
      return `Added via ${playbook_name}`;
    } else if (addedBy) {
      return `Added by ${addedBy}`;
    }
    return 'System';
  }

  _formatTime(timestamp) {
    const date = new Date(timestamp);
    return date.toLocaleTimeString('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  }

  _formatTimestamp(timestamp) {
    const date = new Date(timestamp);
    return date.toLocaleString('en-US', {
      weekday: 'short',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  }

  _formatTickLabel(timestamp) {
    const date = new Date(timestamp);
    return date.toLocaleTimeString('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  }

  _generateTicks() {
    if (!this._minTime || !this._maxTime) return [];

    const ticks = [];
    const range = this._maxTime - this._minTime;
    const numTicks = 6;

    for (let i = 0; i <= numTicks; i++) {
      const time = this._minTime + (range * i / numTicks);
      ticks.push({
        percent: (i / numTicks) * 100,
        label: this._formatTickLabel(time),
      });
    }

    return ticks;
  }

  _handleMarkerMouseEnter(index) {
    this._highlightedIndex = index;
  }

  _handleMarkerMouseLeave() {
    this._highlightedIndex = -1;
  }

  _handleEventMouseEnter(index) {
    this._highlightedIndex = index;
  }

  _handleEventMouseLeave() {
    this._highlightedIndex = -1;
  }

  _handleEventClick(item) {
    this.dispatchEvent(new CustomEvent('timeline-item-click', {
      detail: item,
      bubbles: true,
      composed: true,
    }));
  }

  render() {
    if (!this._processedData || this._processedData.length === 0) {
      return html`
        <div class="widget-container">
          <div class="widget-header">
            <div class="widget-title">Activity</div>
          </div>
          <div class="no-data">No timeline data available</div>
        </div>
      `;
    }

    const ticks = this._generateTicks();

    return html`
      <div class="widget-container">
        <div class="widget-header">
          <div class="widget-title">Activity</div>
        </div>

        <!-- Timeline with dots -->
        <div class="timeline-section">
          <div class="timeline-track">
            <div class="timeline-elements">
              ${this._processedData.map((item, idx) => {
                // Determine tooltip alignment based on position
                const tooltipAlign = item.xPercent < 20 ? 'tooltip-left' 
                  : item.xPercent > 80 ? 'tooltip-right' 
                  : '';

                return html`
                  <div
                    class="timeline-marker ${this._highlightedIndex === idx ? 'highlighted' : ''}"
                    style="left: ${item.xPercent}%"
                    @mouseenter=${() => this._handleMarkerMouseEnter(idx)}
                    @mouseleave=${this._handleMarkerMouseLeave}
                    @click=${() => this._handleEventClick(item)}
                  >
                    <div class="tooltip ${tooltipAlign}">
                      <div class="tooltip-header">
                        <span class="tooltip-source">${item.formattedSource}</span>
                        <span class="tooltip-time">${item.formattedTime}</span>
                      </div>
                      <div class="tooltip-title">${item.title || 'Event'}</div>
                      ${item.details ? html`
                        <div class="tooltip-details">${item.details}</div>
                      ` : ''}
                    </div>
                  </div>
                `;
              })}
              <div class="timeline-line"></div>
            </div>
          </div>

          <div class="time-frame">
            ${ticks.map(tick => html`
              <div class="time-increment">
                <div class="time-label">${tick.label}</div>
              </div>
            `)}
          </div>
        </div>

        <!-- Event List grouped by date -->
        <div class="event-list-section">
          ${this._dateGroups ? Array.from(this._dateGroups.entries()).map(([dateKey, events]) => html`
            <div class="date-stamp">
              <div class="date-stamp-spacer"></div>
              <div class="date-stamp-label">${dateKey}</div>
            </div>

            ${events.map((item, idx) => {
              // Determine position classes for line visibility
              const isFirst = idx === 0;
              const isLast = idx === events.length - 1;
              const isOnly = events.length === 1;
              const positionClass = isOnly ? 'only-in-group' 
                : isFirst ? 'first-in-group' 
                : isLast ? 'last-in-group' 
                : '';

              return html`
                <div
                  class="event-card-wrapper ${positionClass} ${this._highlightedIndex === item.listIndex ? 'highlighted' : ''}"
                  @mouseenter=${() => this._handleEventMouseEnter(item.listIndex)}
                  @mouseleave=${this._handleEventMouseLeave}
                >
                  <div class="event-dot-column">
                    <div class="event-dot-line"></div>
                    <div class="event-dot"></div>
                  </div>
                  <div
                    class="event-card"
                    @click=${() => this._handleEventClick(item)}
                  >
                    <div class="event-header">
                      <span class="event-source">${item.formattedSource}</span>
                      <span class="event-time">${item.formattedTime}</span>
                    </div>
                    <div class="event-title">${item.title || 'Event'}</div>
                    ${item.details ? html`
                      <div class="event-details">${item.details}</div>
                    ` : ''}
                  </div>
                </div>
              `;
            })}
          `) : ''}
        </div>
      </div>
    `;
  }
}

