import { SwimlaneElement, css, html } from '@swimlane/swimlane-element@2';
import { recordFrameTemplate } from '@swimlane/swimlane-element@2/lib/templates.js';

import 'https://widgets.swimlane.app/swim-ui/1/swim-ui.js';

const VERSION = '2.2.0';

/**
 * Case hierarchy graph widget.
 *
 * Renders the current case in the middle, the cases referenced by its PARENT reference field above it,
 * and the cases referenced by its CHILD reference field below it, connected by directional arrows
 * (parent -> current -> child). Each case shows an icon titled with its Tracking Id and signal name,
 * plus its observables: "shared" (in common with the current case) and "associated" (all of its own).
 * Parent/child cases can be unlinked from the current case with the "x" control.
 */
const config = {
  /** Reference-type field key on the current record that holds PARENT case ids. */
  parentField: 'parent-case',
  /** Reference-type field key on the current record that holds CHILD case ids. */
  childField: 'child-cases',
  /** Field key (on every case) holding observables. Text (comma/newline separated), list, or array. */
  observablesField: 'observables',
  /**
   * Field key for the case/signal name shown in each node title. When not set or not found, a likely
   * name field is auto-detected (e.g. "Signal Name", "Name", "Title").
   */
  nameField: 'signal-name',
  /** Remove the unlinked case id from the reference field and save the record when "x" is clicked. */
  triggerSaveOnUnlink: true,
  /** Max observable chips shown per group before collapsing into "+N more". */
  maxObservablesShown: 8,
  /** Optional explicit application name for related cases; defaults to each reference field's target. */
  casesApplicationName: ''
};

const NAME_KEY_CANDIDATES = ['signal-name', 'name', 'case-name', 'title', 'subject', 'summary'];
const NAME_LABEL_CANDIDATES = ['signal name', 'name', 'title', 'subject'];

function getContext(el) {
  let ctx =
    el?.['context-data'] ||
    el?.contextData ||
    (typeof window !== 'undefined' ? window?.swimlane?.contextData : null) ||
    el?.record?.contextData ||
    {};
  if (!ctx.origin && typeof window !== 'undefined' && window.location?.origin) {
    ctx = { ...ctx, origin: window.location.origin };
  }
  return ctx;
}

function apiBase(ctx) {
  const { origin, tenantPath: tp, accountId, tenantId } = ctx;
  let tenantPath = tp;
  if (!tenantPath && accountId && tenantId) {
    tenantPath = `account/${accountId}/tenant/${tenantId}/`;
  }
  if (!origin || !tenantPath) {
    return null;
  }
  return `${origin}/api/${tenantPath}`;
}

/** Unwraps a raw Swimlane field value (handles `{ value }` / `{ name }` wrappers and arrays). */
function resolveValue(raw) {
  if (raw == null) {
    return '';
  }
  if (Array.isArray(raw)) {
    return raw.map(resolveValue).filter(v => v !== '').join(', ');
  }
  if (typeof raw === 'object') {
    if ('value' in raw) {
      return resolveValue(raw.value);
    }
    if ('name' in raw) {
      return resolveValue(raw.name);
    }
    return '';
  }
  return raw;
}

/** Normalizes an observables field value into a de-duplicated array of strings. */
function toObservableList(raw) {
  if (raw == null) {
    return [];
  }
  let items = [];
  if (Array.isArray(raw)) {
    items = raw.map(resolveValue);
  } else if (typeof raw === 'object') {
    items = [resolveValue(raw)];
  } else if (typeof raw === 'string') {
    items = raw.split(/[\n,;]+/);
  } else {
    items = [String(raw)];
  }
  const seen = new Set();
  const out = [];
  for (const item of items) {
    const v = String(item == null ? '' : item).trim();
    if (!v) {
      continue;
    }
    const key = v.toLowerCase();
    if (!seen.has(key)) {
      seen.add(key);
      out.push(v);
    }
  }
  return out;
}

/** Resolves a name/signal-name field key within a field list, with fallbacks. */
function findNameFieldKey(fields, trackingKey, configured) {
  const byKey = {};
  for (const f of fields || []) {
    byKey[f.key] = f;
  }
  const want = (configured || '').trim();
  if (want && byKey[want]) {
    return want;
  }
  for (const key of NAME_KEY_CANDIDATES) {
    if (byKey[key] && byKey[key].key !== trackingKey) {
      return key;
    }
  }
  for (const label of NAME_LABEL_CANDIDATES) {
    const f = (fields || []).find(x => (x.name || '').trim().toLowerCase() === label && x.key !== trackingKey);
    if (f) {
      return f.key;
    }
  }
  return '';
}

