  constructor() {
    super();
    console.log(`Case Hierarchy Graph v${VERSION}`);
    this.setConfig(config);
    this._initState = 'idle';
    this._initError = '';
    this._loadState = 'idle';
    this._current = null;
    this._parents = [];
    this._children = [];
    this._appSchemaCache = {};
    this._initStarted = false;
    this._loadedOnce = false;
    this._loadedSignature = null;
    this._loadingSignature = null;
    this._pendingReload = false;
  }

  setConfig(userConfig, replaceAll = false) {
    this.config = replaceAll ? { ...config, ...userConfig } : { ...this.config, ...userConfig };
  }

  connectedCallback() {
    super.connectedCallback();
    this._maybeInit();
  }

  updated(changed) {
    super.updated(changed);
    if (changed.has('contextData') || changed.has('context-data') || changed.has('record')) {
      this._maybeInit();
    }
  }

  _maybeInit() {
    if (this._initState === 'ready' || this._initStarted) {
      this._maybeLoad();
      return;
    }
    if (!apiBase(getContext(this)) || !this.contextData?.application) {
      return;
    }
    this._initStarted = true;
    this._initialize();
  }

  async _fetchJson(url, init) {
    const res = await fetch(url, {
      credentials: 'include',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      ...init
    });
    const text = await res.text();
    let body;
    try {
      body = text ? JSON.parse(text) : null;
    } catch {
      body = text;
    }
    if (!res.ok) {
      const msg = typeof body === 'object' && body && body.message ? body.message : text || res.statusText;
      throw new Error(msg || `HTTP ${res.status}`);
    }
    return body;
  }

  async _initialize() {
    this._initState = 'loading';
    this._initError = '';
    this.requestUpdate();
    try {
      const app = this.contextData.application;
      this._appSchemaCache[app.id] = app;
      this._initState = 'ready';
      this._maybeLoad();
    } catch (e) {
      console.error('[case-hierarchy] init', e);
      this._initState = 'error';
      this._initError = e?.message || String(e);
      this._initStarted = false;
    }
    this.requestUpdate();
  }

  /** Signature of the parent/child reference ids; changes when those fields are updated. */
  _hierarchySignature() {
    const sortJoin = ids => [...ids].sort().join(',');
    return `${sortJoin(this._referencedIds(this.config.parentField))}|${sortJoin(
      this._referencedIds(this.config.childField)
    )}`;
  }

  /** Loads on first ready, and reloads whenever the parent/child fields change. */
  _maybeLoad() {
    if (this._initState !== 'ready' || !this.record?.id) {
      return;
    }
    const signature = this._hierarchySignature();
    if (this._loadState === 'loading') {
      // A change arrived mid-load; reload once the current load settles.
      if (signature !== this._loadingSignature) {
        this._pendingReload = true;
      }
      return;
    }
    if (this._loadedOnce && signature === this._loadedSignature) {
      return;
    }
    this._loadGraph(signature);
  }

  async _getAppSchema(appId) {
    if (this._appSchemaCache[appId]) {
      return this._appSchemaCache[appId];
    }
    const base = apiBase(getContext(this));
    const app = await this._fetchJson(`${base}app/${appId}`, { method: 'GET' });
    this._appSchemaCache[appId] = app;
    return app;
  }

  _buildCurrentNode() {
    const app = this.contextData.application;
    const fields = app.fields || [];
    const trackingField = fields.find(f => f.fieldType === 'tracking');
    const nameKey = findNameFieldKey(fields, trackingField?.key, this.config.nameField);
    const trackingId = trackingField ? resolveValue(this.record[trackingField.key]) : '';
    const name = nameKey ? resolveValue(this.record[nameKey]) : '';
    const observables = toObservableList(this.record[this.config.observablesField]);
    return {
      id: this.record.id,
      appId: app.id,
      trackingId: trackingId || this.record.id,
      name,
      observables,
      shared: [],
      kind: 'current'
    };
  }

  /** Normalizes a reference field value into an array of record id strings. */
  _referencedIds(fieldKey) {
    const raw = this.record?.[fieldKey];
    if (!Array.isArray(raw)) {
      return raw ? [resolveValue(raw)].filter(Boolean) : [];
    }
    return raw.map(v => (v && typeof v === 'object' ? v.id || v.value || resolveValue(v) : v)).filter(Boolean);
  }

  async _loadRelated(fieldKey, kind, currentObservables) {
    const app = this.contextData.application;
    const field = (app.fields || []).find(f => f.key === fieldKey);
    if (!field) {
      return [];
    }
    const ids = this._referencedIds(fieldKey);
    if (!ids.length) {
      return [];
    }

    const targetAppId = field.targetId || app.id;
    const schema = await this._getAppSchema(targetAppId);
    const sfields = schema.fields || [];
    const trackingField = sfields.find(f => f.fieldType === 'tracking');
    const nameKey = findNameFieldKey(sfields, trackingField?.key, this.config.nameField);
    const nameField = nameKey ? sfields.find(f => f.key === nameKey) : null;
    const obsField = sfields.find(f => f.key === this.config.observablesField);

    const base = apiBase(getContext(this));
    const currentSet = new Set((currentObservables || []).map(o => o.toLowerCase()));

    const nodes = await Promise.all(
      ids.map(async id => {
        try {
          const rec = await this._fetchJson(`${base}app/${targetAppId}/record/${id}`, { method: 'GET' });
          const values = rec.values || {};
          const trackingId = trackingField ? resolveValue(values[trackingField.id]) : '';
          const name = nameField ? resolveValue(values[nameField.id]) : '';
          const observables = obsField ? toObservableList(values[obsField.id]) : [];
          const shared = observables.filter(o => currentSet.has(o.toLowerCase()));
          return {
            id: rec.id || id,
            appId: targetAppId,
            fieldKey,
            kind,
            trackingId: trackingId || rec.id || id,
            name,
            observables,
            shared
          };
        } catch (e) {
          console.warn(`[case-hierarchy] could not load ${kind} case ${id}`, e);
          return null;
        }
      })
    );
    return nodes.filter(Boolean);
  }

  async _loadGraph(signature = this._hierarchySignature()) {
    this._loadState = 'loading';
    this._loadingSignature = signature;
    this._pendingReload = false;
    this.requestUpdate();
    try {
      const current = this._buildCurrentNode();
      const [parents, children] = await Promise.all([
        this._loadRelated(this.config.parentField, 'parent', current.observables),
        this._loadRelated(this.config.childField, 'child', current.observables)
      ]);
      this._current = current;
      this._parents = parents;
      this._children = children;
      this._loadState = 'ready';
      this._loadedOnce = true;
      this._loadedSignature = signature;
    } catch (e) {
      console.error('[case-hierarchy] load', e);
      this._loadState = 'error';
      this._initError = e?.message || String(e);
    }
    this.requestUpdate();

    // A parent/child change arrived while loading — reload to reflect the latest values.
    if (this._pendingReload && this._loadState !== 'error') {
      this._pendingReload = false;
      this._maybeLoad();
    }
  }

  async _unlink(node) {
    const fieldKey = node.fieldKey;
    const remaining = this._referencedIds(fieldKey).filter(id => id !== node.id);

    this.updateRecordValue(fieldKey, remaining);

    if (node.kind === 'parent') {
      this._parents = this._parents.filter(n => n.id !== node.id);
    } else {
      this._children = this._children.filter(n => n.id !== node.id);
    }

    // Keep the loaded signature in sync so this self-initiated change doesn't trigger a reload.
    const sortJoin = ids => [...ids].sort().join(',');
    const parentIds = node.kind === 'parent' ? remaining : this._referencedIds(this.config.parentField);
    const childIds = node.kind === 'child' ? remaining : this._referencedIds(this.config.childField);
    this._loadedSignature = `${sortJoin(parentIds)}|${sortJoin(childIds)}`;
    this.requestUpdate();

    if (this.config.triggerSaveOnUnlink) {
      try {
        await this.triggerSave();
        this.triggerNotification('success', 'Case unlinked', `Removed ${node.trackingId} from the hierarchy.`);
      } catch (err) {
        console.error('[case-hierarchy] unlink save', err);
        this.triggerNotification('error', 'Unlink failed', err?.message || String(err));
      }
    }
  }

  /** Opens the case in a record drawer (same preview used for referenced records). */
  async _openPreview(node) {
    if (!node?.appId || !node?.id) {
      return;
    }
    try {
      await this.openRecord(node.appId, node.id);
    } catch (err) {
      console.error('[case-hierarchy] preview', err);
      this.triggerNotification('error', 'Preview failed', err?.message || String(err));
    }
  }

  // ---- render ----

  render() {
    if (this._initState === 'error' || this._loadState === 'error') {
      return recordFrameTemplate(html`
        <div class="chg"><div class="chg__err">${this._initError}</div></div>
      `);
    }
    if (this._initState !== 'ready') {
      return recordFrameTemplate(html`
        <div class="chg">
          <div class="chg__spinner">
            <swim-progress-spinner mode="indeterminate"></swim-progress-spinner>
            <span>Loading…</span>
          </div>
        </div>
      `);
    }
    if (!this.record?.id) {
      return recordFrameTemplate(html`
        <div class="chg"><div class="chg__hint">Save the case to view its hierarchy.</div></div>
      `);
    }
    if (this._loadState === 'loading' || !this._current) {
      return recordFrameTemplate(html`
        <div class="chg">
          <div class="chg__spinner">
            <swim-progress-spinner mode="indeterminate"></swim-progress-spinner>
            <span>Building case hierarchy…</span>
          </div>
        </div>
      `);
    }

    const hasParents = this._parents.length > 0;
    const hasChildren = this._children.length > 0;

    return recordFrameTemplate(html`
      <div class="chg">
        ${hasParents
          ? html`
              <div class="chg__section-label">Parent ${this._parents.length === 1 ? 'case' : 'cases'}</div>
              <div class="chg__row">${this._parents.map(n => this._renderNode(n))}</div>
              <swim-icon class="chg__arrow" font-icon="arrow-down" font-set="lit"></swim-icon>
            `
          : null}

        <div class="chg__section-label">Current case</div>
        <div class="chg__row">${this._renderNode(this._current)}</div>

        ${hasChildren
          ? html`
              <swim-icon class="chg__arrow" font-icon="arrow-down" font-set="lit"></swim-icon>
              <div class="chg__section-label">Child ${this._children.length === 1 ? 'case' : 'cases'}</div>
              <div class="chg__row">${this._children.map(n => this._renderNode(n))}</div>
            `
          : null}

        ${!hasParents && !hasChildren
          ? html`<div class="chg__hint">No linked parent or child cases.</div>`
          : null}
      </div>
    `);
  }

  _renderNode(node) {
    const isCurrent = node.kind === 'current';
    const clickable = !isCurrent;
    const onActivate = clickable ? () => this._openPreview(node) : null;
    return html`
      <div
        class="chg__node ${isCurrent ? 'chg__node--current' : ''} ${clickable ? 'chg__node--clickable' : ''}"
        role=${clickable ? 'button' : 'group'}
        tabindex=${clickable ? '0' : '-1'}
        title=${clickable ? `Preview ${node.trackingId}` : ''}
        @click=${onActivate}
        @keydown=${clickable
          ? e => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                this._openPreview(node);
              }
            }
          : null}
      >
        <div class="chg__node-head">
          <swim-icon class="chg__node-icon" font-icon="document" font-set="lit"></swim-icon>
          <div class="chg__node-title">
            <span class="chg__node-id">${node.trackingId}</span>
            ${node.name ? html`<span class="chg__node-name">${node.name}</span>` : null}
          </div>
          ${clickable
            ? html`<swim-icon class="chg__preview-icon" font-icon="eye" font-set="lit" title="Preview case"></swim-icon>`
            : null}
          ${!isCurrent
            ? html`
                <button
                  class="chg__remove"
                  title="Unlink case"
                  aria-label="Unlink ${node.trackingId}"
                  @click=${e => {
                    e.stopPropagation();
                    this._unlink(node);
                  }}
                >
                  <swim-icon font-icon="x" font-set="lit"></swim-icon>
                </button>
              `
            : null}
        </div>
        ${isCurrent
          ? this._renderObsGroup('Observables', node.observables, false)
          : html`
              ${this._renderObsGroup('Shared observables', node.shared, true)}
              ${this._renderObsGroup('Associated observables', node.observables, false)}
            `}
      </div>
    `;
  }

  _renderObsGroup(label, list, shared) {
    if (!list || !list.length) {
      return null;
    }
    const max = Math.max(1, Number(this.config.maxObservablesShown) || 8);
    const shown = list.slice(0, max);
    const extra = list.length - shown.length;
    return html`
      <div class="chg__obs-group">
        <span class="chg__obs-label">${label} (${list.length})</span>
        <div class="chg__chips">
          ${shown.map(o => html`<span class="chg__chip ${shared ? 'chg__chip--shared' : ''}" title=${o}>${o}</span>`)}
          ${extra > 0 ? html`<span class="chg__chip">+${extra} more</span>` : null}
        </div>
      </div>
    `;
  }
}

