/**
 * MITRE ATT&CK case TTP tracker — tactics as horizontal columns; techniques as distinct cards.
 * @version 1.9.34
 */
import { SwimlaneElement, css, html, svg } from '@swimlane/swimlane-element@2';
import { recordFrameTemplate } from '@swimlane/swimlane-element@2/lib/templates.js';
import { repeat } from 'lit-html@2/directives/repeat.js';
import 'https://widgets.swimlane.app/swim-ui/1/swim-ui.js';

/** Prefer plural first — Turbine apps often use `mitre-attack-techniques` on the record API. */
const MITRE_FIELD_KEYS_TO_TRY = ['mitre-attack-techniques', 'mitre-attack-technique'];

const DEFAULT_FIELD_KEY = 'mitre-attack-techniques';

/**
 * Empty fallback when `loadFullMitreCatalog` is false or enterprise STIX fetch fails (picker disabled / empty until catalog loads).
 */
const EMBEDDED_FALLBACK_CATALOG = [];

/**
 * Full enterprise ATT&CK STIX 2.0 bundle (all tactics + techniques with kill-chain phases).
 * The `attack-stix-data` repo’s `enterprise-attack.json` is often collection metadata only — use `mitre/cti` for parsing here.
 */
const DEFAULT_MITRE_STIX_JSON_URL =
  'https://raw.githubusercontent.com/mitre/cti/master/enterprise-attack/enterprise-attack.json';

/** Default max width (px) for tactic/technique `swim-select` in the picker bar. */
const DEFAULT_PICKER_SELECT_MAX_WIDTH = 520;

/**
 * Max procedure-example strings per technique when parsing MITRE STIX (from `uses` relationship
 * descriptions). Keeps record payloads bounded; order follows bundle iteration (deduped).
 */
const MITRE_STIX_PROCEDURE_EXAMPLES_MAX = 20;

/** sessionStorage key prefix; full key includes URL + version so overrides do not collide. */
const MITRE_STIX_SESSION_CACHE_PREFIX = 'swimlane_widget_mitre_stix_cache:';

/** Bump when parsed catalog shape or parser changes so stale session entries are ignored. */
const MITRE_STIX_SESSION_CACHE_VERSION = 'v2';

function getSessionStorageMitreCatalogKey(url) {
  return `${MITRE_STIX_SESSION_CACHE_PREFIX}${MITRE_STIX_SESSION_CACHE_VERSION}:${encodeURIComponent(String(url || ''))}`;
}

function isValidCachedTacticsPayload(parsed) {
  if (!Array.isArray(parsed) || parsed.length === 0) return false;
  for (let i = 0; i < Math.min(parsed.length, 8); i++) {
    const t = parsed[i];
    if (!t || typeof t !== 'object') return false;
    if (!Array.isArray(t.techniques)) return false;
    if (t.id == null && t.name == null) return false;
    for (const tech of t.techniques.slice(0, 4)) {
      if (!tech || typeof tech !== 'object') return false;
      if (!Object.prototype.hasOwnProperty.call(tech, 'procedures')) return false;
      if (!Array.isArray(tech.procedures)) return false;
    }
  }
  return true;
}

/**
 * @returns {object[] | null} Parsed tactics array or null on miss / error.
 */
function readMitreCatalogFromSessionStorage(url) {
  try {
    if (typeof sessionStorage === 'undefined') return null;
    const key = getSessionStorageMitreCatalogKey(url);
    const raw = sessionStorage.getItem(key);
    if (raw == null || raw === '') return null;
    const parsed = JSON.parse(raw);
    if (!isValidCachedTacticsPayload(parsed)) return null;
    return parsed;
  } catch {
    return null;
  }
}

function writeMitreCatalogToSessionStorage(url, tactics) {
  try {
    if (typeof sessionStorage === 'undefined') return;
    if (!Array.isArray(tactics) || tactics.length === 0) return;
    const key = getSessionStorageMitreCatalogKey(url);
    sessionStorage.setItem(key, JSON.stringify(tactics));
  } catch (e) {
    if (typeof console !== 'undefined' && console.debug) {
      console.debug('mitre-attack-ttp: sessionStorage cache write skipped', e);
    }
  }
}

function stripMitreProcedureExampleText(raw) {
  if (typeof raw !== 'string') return '';
  let s = raw.trim();
  s = s.replace(/\(Citation:[^)]*\)/gi, '');
  s = s.replace(/\[([^\]]+)\]\([^)]*\)/g, '$1');
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}

function dedupeCapMitreProcedureExamples(rawStrings, max) {
  const seen = new Set();
  const out = [];
  for (const raw of rawStrings) {
    const line = stripMitreProcedureExampleText(raw);
    if (!line) continue;
    const key = line.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(line);
    if (out.length >= max) break;
  }
  return out;
}

/**
 * Parse MITRE enterprise-attack.json bundle into { id, name, url?, techniques[] } tactics (widget shape).
 */
function parseEnterpriseAttackToTactics(bundle) {
  const objects = bundle?.objects;
  if (!Array.isArray(objects)) return [];

  const byShort = new Map();

  for (const obj of objects) {
    if (obj.type !== 'x-mitre-tactic' || obj.revoked) continue;
    const ext = (obj.external_references || []).find(r => r.source_name === 'mitre-attack');
    const tid = ext?.external_id;
    if (!tid || !tid.startsWith('TA')) continue;
    const short = obj.x_mitre_shortname;
    if (!short) continue;
    byShort.set(short, {
      id: tid,
      name: obj.name || tid,
      url: ext?.url || null,
      techniques: []
    });
  }

  /** Sub-technique STIX id -> parent technique STIX id (`subtechnique-of`: source = sub, target = parent). */
  const subToParent = new Map();
  for (const obj of objects) {
    if (obj.type !== 'relationship' || obj.revoked) continue;
    if (obj.relationship_type !== 'subtechnique-of') continue;
    subToParent.set(obj.source_ref, obj.target_ref);
  }

  const patternsById = new Map();
  for (const obj of objects) {
    if (obj.type === 'attack-pattern' && obj.id) patternsById.set(obj.id, obj);
  }

  /** Procedure examples: `uses` relationships targeting an attack-pattern carry human-readable text in `description`. */
  const procedureRawByStixId = new Map();
  for (const obj of objects) {
    if (obj.type !== 'relationship' || obj.revoked) continue;
    if (obj.relationship_type !== 'uses') continue;
    const targetRef = obj.target_ref;
    if (!targetRef || !patternsById.has(targetRef)) continue;
    const relDesc = obj.description;
    if (typeof relDesc !== 'string' || !relDesc.trim()) continue;
    if (!procedureRawByStixId.has(targetRef)) procedureRawByStixId.set(targetRef, []);
    procedureRawByStixId.get(targetRef).push(relDesc);
  }

  function mitreAttackRef(obj) {
    const ext = (obj.external_references || []).find(r => r.source_name === 'mitre-attack');
    if (!ext?.external_id) return null;
    return { id: ext.external_id, url: ext.url || null };
  }

  /** Kill-chain phases for enterprise matrix; sub-techniques inherit from parent when missing. */
  function mitrePhasesForPattern(obj) {
    const chain = [];
    let cur = obj;
    const seen = new Set();
    while (cur && !seen.has(cur.id)) {
      seen.add(cur.id);
      const phases = (cur.kill_chain_phases || []).filter(p => p.kill_chain_name === 'mitre-attack');
      if (phases.length) return phases;
      const parentRef = subToParent.get(cur.id);
      cur = parentRef ? patternsById.get(parentRef) : null;
    }
    return [];
  }

  for (const obj of objects) {
    if (obj.type !== 'attack-pattern' || obj.revoked || obj.x_mitre_deprecated) continue;
    const ref = mitreAttackRef(obj);
    const techId = ref?.id;
    if (!techId || !techId.startsWith('T')) continue;
    const phases = mitrePhasesForPattern(obj);
    const procRaw = procedureRawByStixId.get(obj.id) || [];
    const procedures = dedupeCapMitreProcedureExamples(procRaw, MITRE_STIX_PROCEDURE_EXAMPLES_MAX);
    const tech = {
      id: techId,
      name: obj.name || techId,
      url: ref.url,
      procedures
    };
    for (const ph of phases) {
      const tactic = byShort.get(ph.phase_name);
      if (!tactic) continue;
      if (!tactic.techniques.some(t => t.id === techId)) {
        tactic.techniques.push({ ...tech });
      }
    }
  }

  const tactics = [...byShort.values()].filter(t => t.techniques.length > 0);
  tactics.sort((a, b) => {
    const na = parseInt(String(a.id).replace(/^TA/i, ''), 10) || 0;
    const nb = parseInt(String(b.id).replace(/^TA/i, ''), 10) || 0;
    return na - nb;
  });
  for (const t of tactics) {
    t.techniques.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
  }
  return tactics;
}

function unwrapRecordField(raw, depth = 0) {
  if (raw == null || depth > 10) return raw;
  if (typeof raw === 'string' || typeof raw === 'number' || typeof raw === 'boolean') return raw;
  if (Array.isArray(raw)) return raw;
  if (typeof raw === 'object') {
    if (Object.prototype.hasOwnProperty.call(raw, 'tactics')) return raw;
    if (Object.prototype.hasOwnProperty.call(raw, 'value') && raw.value !== undefined) {
      return unwrapRecordField(raw.value, depth + 1);
    }
  }
  return raw;
}

/** Read one field from a plain record object (`key`, `values`, `fields`) without `this`. */
function readRecordFieldRawFromRecordObject(rec, key) {
  if (!rec || key == null) return undefined;
  let v = rec[key];
  if (v === undefined && rec.values != null && typeof rec.values === 'object' && !Array.isArray(rec.values)) {
    v = rec.values[key];
  }
  if (v === undefined && rec.fields != null && typeof rec.fields === 'object' && !Array.isArray(rec.fields)) {
    v = rec.fields[key];
  }
  return v;
}

/** Raw case rows: `{ tactics: [{ uid, name }], technique: { uid, name } | string }[]` */
function isAlertMitreTacticTechniqueRow(obj) {
  return (
    obj &&
    typeof obj === 'object' &&
    obj.technique != null &&
    Array.isArray(obj.tactics)
  );
}

/**
 * Expand alert integration rows into widget tactics (one column per tactic id; a technique linked to
 * multiple tactics appears under each column).
 */
function parseAlertMitreArrayToTactics(rows) {
  if (!Array.isArray(rows)) return [];
  const map = new Map();
  for (const row of rows) {
    if (!isAlertMitreTacticTechniqueRow(row)) continue;
    const tp =
      typeof row.technique === 'string' || typeof row.technique === 'number'
        ? { id: String(row.technique), name: String(row.technique) }
        : row.technique;
    if (!tp || typeof tp !== 'object') continue;
    const tech = normalizeTechniqueShape({
      id: tp.uid ?? tp.id,
      name: tp.name,
      procedures: tp.procedures
    });
    if (!tech) continue;
    for (const tac of row.tactics) {
      const tid = String(tac?.uid ?? tac?.id ?? '').trim();
      const tname = String(tac?.name ?? '').trim() || tid;
      if (!tid && !tname) continue;
      const k = tid || tname;
      if (!map.has(k)) {
        map.set(k, { id: tid || k, name: tname || tid || 'Tactic', techniques: [] });
      }
      const bucket = map.get(k);
      if (!bucket.techniques.some(t => t.id === tech.id)) {
        bucket.techniques.push({ ...tech });
      }
    }
  }
  return [...map.values()];
}

/** Canonical tactics → alert row array (one row per tactic–technique pair; multi-tactic source becomes multiple rows). */
function mitreNameNorm(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function mitreNameSlug(s) {
  const base = String(s || '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
  return base || 'x';
}

/** One line: `Tactic / Technique` (flexible spaces around `/`). */
function splitMitreTacticTechniqueLine(line) {
  const s = String(line).trim();
  const m = s.match(/^(.+?)\s*\/\s*(.+)$/);
  if (!m) return null;
  const tactic = m[1].trim();
  const technique = m[2].trim();
  if (!tactic || !technique) return null;
  return { tactic, technique };
}

/** Multiline plain text: at least one line matches `Tactic / Technique`. */
function isMitreNameLinesString(s) {
  const t = String(s).trim();
  if (!t) return false;
  if (t.startsWith('{') || t.startsWith('[')) return false;
  return t.split(/\r?\n/).some(l => splitMitreTacticTechniqueLine(l));
}

function looksLikeMitreMatrixTacticId(id) {
  const s = String(id ?? '').trim();
  return /^TA\d{4}$/i.test(s) || /^TA-NAME-/i.test(s);
}

function isCanonicalMitreTacticId(id) {
  return /^TA\d{4}$/i.test(String(id ?? '').trim());
}

function isCanonicalMitreTechniqueId(id) {
  return /^T\d{4}(\.\d{3})?$/i.test(String(id ?? '').trim());
}

/** Fallback MITRE ATT&CK URL from a canonical id when catalog entry has no `url`. */
function mitreAttackUrlFromId(id, kind) {
  const sid = String(id ?? '').trim();
  if (!sid) return null;
  if (kind === 'tactic' || (kind == null && isCanonicalMitreTacticId(sid))) {
    if (!isCanonicalMitreTacticId(sid)) return null;
    return `https://attack.mitre.org/tactics/${sid.toUpperCase()}/`;
  }
  if (kind === 'technique' || (kind == null && isCanonicalMitreTechniqueId(sid))) {
    if (!isCanonicalMitreTechniqueId(sid)) return null;
    const upper = sid.toUpperCase();
    const m = upper.match(/^T(\d{4})(?:\.(\d{3}))?$/);
    if (!m) return null;
    if (m[2]) return `https://attack.mitre.org/techniques/T${m[1]}/${m[2]}/`;
    return `https://attack.mitre.org/techniques/T${m[1]}/`;
  }
  return null;
}

/**
 * Resolve a MITRE ATT&CK page URL for display (catalog `url` first, then canonical id template).
 * @param {'tactic' | 'technique'} kind
 */
function resolveMitreAttackUrl(id, catalog, kind) {
  const sid = String(id ?? '').trim();
  if (!sid || !kind) return null;
  const cat = Array.isArray(catalog) ? catalog : [];
  if (kind === 'tactic') {
    const tac = cat.find(t => String(t?.id ?? '').trim() === sid);
    if (typeof tac?.url === 'string' && tac.url.trim()) return tac.url.trim();
    return mitreAttackUrlFromId(sid, 'tactic');
  }
  if (kind === 'technique') {
    for (const tac of cat) {
      const tech = (tac.techniques || []).find(t => String(t?.id ?? '').trim() === sid);
      if (typeof tech?.url === 'string' && tech.url.trim()) return tech.url.trim();
    }
    return mitreAttackUrlFromId(sid, 'technique');
  }
  return null;
}

/** Every column has no techniques and ids are not normal MITRE tactic ids (e.g. platform internal uids). */
function tacticsLookLikeEmptyShellColumns(tactics) {
  if (!Array.isArray(tactics) || tactics.length === 0) return false;
  for (const t of tactics) {
    if ((t.techniques || []).length > 0) return false;
  }
  return tactics.every(t => !looksLikeMitreMatrixTacticId(t.id));
}

function gatherMitreNameLineStringsFromObject(root, maxDepth = 10, maxStrings = 48) {
  const found = [];
  const seen = new WeakSet();
  function walk(x, depth) {
    if (x == null || depth > maxDepth || found.length >= maxStrings) return;
    if (typeof x === 'string') {
      if (x.length > 6 && isMitreNameLinesString(x)) found.push(x);
      return;
    }
    if (typeof x !== 'object') return;
    if (seen.has(x)) return;
    seen.add(x);
    if (Array.isArray(x)) {
      const lim = Math.min(x.length, 80);
      for (let i = 0; i < lim; i++) walk(x[i], depth + 1);
      return;
    }
    for (const k of Object.keys(x)) walk(x[k], depth + 1);
  }
  walk(root, 0);
  return found;
}

function findTacticInCatalogByName(catalog, tacticName) {
  const n = mitreNameNorm(tacticName);
  if (!n || !Array.isArray(catalog)) return null;
  for (const t of catalog) {
    if (mitreNameNorm(t.name) === n || mitreNameNorm(String(t.id ?? '')) === n) return t;
  }
  return null;
}

function findTechniqueUnderTacticEntry(tacticEntry, techName) {
  const n = mitreNameNorm(techName);
  if (!n || !tacticEntry?.techniques) return null;
  for (const x of tacticEntry.techniques) {
    if (mitreNameNorm(x.name) === n || mitreNameNorm(String(x.id ?? '')) === n) return x;
  }
  return null;
}

function findTechniqueAnywhereInCatalog(catalog, techName) {
  const n = mitreNameNorm(techName);
  if (!n || !Array.isArray(catalog)) return null;
  for (const tac of catalog) {
    for (const x of tac.techniques || []) {
      if (mitreNameNorm(x.name) === n || mitreNameNorm(String(x.id ?? '')) === n) return x;
    }
  }
  return null;
}

/** Catalog technique for display enrichment (id first, then name under tactic / anywhere). */
function findCatalogTechniqueForEnrichment(catalog, tacticId, techId, techName) {
  const cat = Array.isArray(catalog) ? catalog : EMBEDDED_FALLBACK_CATALOG;
  if (!cat.length) return null;
  const tid = tacticId != null ? String(tacticId).trim() : '';
  const kid = techId != null ? String(techId).trim() : '';
  const catTac = tid ? cat.find(t => t.id === tid) : null;
  if (catTac && kid) {
    const byId = catTac.techniques?.find(t => t.id === kid);
    if (byId) return byId;
  }
  if (catTac && techName) {
    const byName = findTechniqueUnderTacticEntry(catTac, techName);
    if (byName) return byName;
  }
  if (kid) {
    for (const tac of cat) {
      const hit = tac.techniques?.find(t => t.id === kid);
      if (hit) return hit;
    }
  }
  if (techName) return findTechniqueAnywhereInCatalog(cat, techName);
  return null;
}

/**
 * Fill empty `procedures` on record techniques from the STIX catalog (display-only for string-list / alert shapes).
 */
function enrichTacticsProceduresFromCatalog(tactics, catalog) {
  if (!Array.isArray(tactics) || tactics.length === 0) return tactics;
  const cat = Array.isArray(catalog) ? catalog : EMBEDDED_FALLBACK_CATALOG;
  if (!cat.length) return tactics;

  return tactics.map(tac => {
    const normalized = normalizeTacticShape(tac);
    if (!normalized) return tac;
    const techniques = (normalized.techniques || []).map(tech => {
      const procedures = coerceProcedureStrings(tech.procedures);
      if (procedures.length > 0) return { ...tech, procedures };
      const catTech = findCatalogTechniqueForEnrichment(cat, normalized.id, tech.id, tech.name);
      const fromCatalog = coerceProcedureStrings(catTech?.procedures);
      return fromCatalog.length ? { ...tech, procedures: fromCatalog } : { ...tech, procedures: [] };
    });
    return { ...normalized, techniques };
  });
}

/**
 * Parse `Tactic / Technique` lines into widget tactics; resolve ids from catalog when possible.
 * Same technique name under different tactics stays under each line’s tactic column.
 */
function parseMitreNameLinesToTactics(text, catalog) {
  const cat = Array.isArray(catalog) ? catalog : EMBEDDED_FALLBACK_CATALOG;
  const lines = String(text)
    .split(/\r?\n/)
    .map(l => l.trim())
    .filter(Boolean);
  const map = new Map();

  for (const line of lines) {
    const parts = splitMitreTacticTechniqueLine(line);
    if (!parts) continue;
    const tacticNameRaw = parts.tactic;
    const techniqueNameRaw = parts.technique;

    const catTac = findTacticInCatalogByName(cat, tacticNameRaw);
    const tacticId = catTac ? catTac.id : `TA-NAME-${mitreNameSlug(tacticNameRaw)}`;
    const tacticDisplayName = catTac ? catTac.name : tacticNameRaw;

    let catalogTech =
      catTac && findTechniqueUnderTacticEntry(catTac, techniqueNameRaw);
    if (!catalogTech && cat.length) {
      catalogTech = findTechniqueAnywhereInCatalog(cat, techniqueNameRaw);
    }

    let techId;
    let techDisplayName;
    let procedures = [];
    if (catalogTech) {
      techId = String(catalogTech.id ?? '').trim() || `T-NAME-${mitreNameSlug(techniqueNameRaw)}`;
      techDisplayName = catalogTech.name || techniqueNameRaw;
      procedures = coerceProcedureStrings(catalogTech.procedures);
    } else {
      techId = `T-NAME-${mitreNameSlug(techniqueNameRaw)}`;
      techDisplayName = techniqueNameRaw;
    }

    const tech = normalizeTechniqueShape({
      id: techId,
      name: techDisplayName,
      procedures
    });
    if (!tech) continue;

    if (!map.has(tacticId)) {
      map.set(tacticId, {
        id: tacticId,
        name: tacticDisplayName,
        techniques: []
      });
    }
    const bucket = map.get(tacticId);
    if (!bucket.techniques.some(t => t.id === tech.id)) {
      bucket.techniques.push(tech);
    }
  }

  return [...map.values()].map(normalizeTacticShape).filter(Boolean);
}

function tacticsToMitreNameLinesString(tactics) {
  const lines = [];
  for (const tac of tactics || []) {
    const tName = String(tac.name ?? tac.id ?? '').trim();
    for (const tech of tac.techniques || []) {
      const kName = String(tech.name ?? tech.id ?? '').trim();
      if (tName && kName) lines.push(`${tName} / ${kName}`);
    }
  }
  return lines.join('\n');
}

/** API may return `["Tactic / Technique", ...]` (string[]) for the same logical field as ListItem rows. */
function isSwimlaneMitrePlainStringArray(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return false;
  return arr.every(x => {
    if (typeof x !== 'string') return false;
    return Boolean(splitMitreTacticTechniqueLine(x.trim()));
  });
}

function parseSwimlanePlainStringArrayToTactics(rows, catalog) {
  if (!Array.isArray(rows)) return [];
  const lines = rows.map(r => String(r == null ? '' : r).trim()).filter(Boolean);
  if (lines.length === 0) return [];
  return parseMitreNameLinesToTactics(lines.join('\n'), catalog);
}

/**
 * Swimlane / Turbine multi-value string field: `[{ id?, $type?, value: "Tactic / Technique" }, ...]`
 * (Core.Models.Record.ListItem`1[System.String]).
 */
function isSwimlaneStringListItemArray(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return false;
  const first = arr[0];
  if (!first || typeof first !== 'object') return false;
  if (isAlertMitreTacticTechniqueRow(first)) return false;
  if (typeof first.value !== 'string') return false;
  if (!splitMitreTacticTechniqueLine(first.value.trim())) return false;
  return arr.every(
    x => x && typeof x === 'object' && typeof x.value === 'string' && x.value.trim().length > 0
  );
}

function parseSwimlaneStringListArrayToTactics(rows, catalog) {
  if (!Array.isArray(rows)) return [];
  const lines = rows
    .map(r => (r && typeof r.value === 'string' ? r.value.trim() : ''))
    .filter(Boolean);
  if (lines.length === 0) return [];
  return parseMitreNameLinesToTactics(lines.join('\n'), catalog);
}

/**
 * Persist as **`string[]`** — each entry is one `Tactic / Technique` line. Turbine `setValue` / `formatListItem`
 * typically calls `.trim()` on **each array element**, so objects `{ value }` throw `trim is not a function`.
 */
function tacticsToSwimlaneStringListPlainStrings(orderedTactics) {
  return tacticsToMitreNameLinesString(orderedTactics)
    .split(/\r?\n/)
    .map(l => String(l == null ? '' : l).trim())
    .filter(Boolean);
}

/**
 * Optional: persist as `{ value, id? }[]` when `config.mitreSwimlaneSaveAsListObjects === true` (non-default).
 */
function tacticsToSwimlaneStringListItems(orderedTactics, previousList) {
  const rawLines = tacticsToMitreNameLinesString(orderedTactics)
    .split(/\r?\n/)
    .map(l => String(l == null ? '' : l).trim())
    .filter(Boolean);
  const prev = Array.isArray(previousList) ? previousList : [];
  const idByValue = new Map();
  for (const row of prev) {
    if (!row || typeof row !== 'object') continue;
    const rowVal = row.value;
    const v =
      typeof rowVal === 'string'
        ? rowVal.trim()
        : rowVal != null
          ? String(rowVal).trim()
          : '';
    if (!v) continue;
    const rid = row.id ?? row.uid;
    if (rid != null && String(rid).trim() !== '') {
      idByValue.set(v, String(rid).trim());
    }
  }
  return rawLines
    .map(line => {
      const value = String(line == null ? '' : line).trim();
      if (!value) return null;
      const item = { value };
      const id = idByValue.get(value);
      if (id != null && String(id).trim() !== '') item.id = String(id).trim();
      return item;
    })
    .filter(Boolean);
}

function parseFieldJsonPayload(data, catalog) {
  const cat = Array.isArray(catalog) ? catalog : EMBEDDED_FALLBACK_CATALOG;
  if (Array.isArray(data)) {
    if (data.length > 0 && isSwimlaneMitrePlainStringArray(data)) {
      return parseSwimlanePlainStringArrayToTactics(data, cat);
    }
    if (data.length > 0 && isSwimlaneStringListItemArray(data)) {
      return parseSwimlaneStringListArrayToTactics(data, cat);
    }
    if (data.length > 0 && isAlertMitreTacticTechniqueRow(data[0])) {
      return parseAlertMitreArrayToTactics(data)
        .map(normalizeTacticShape)
        .filter(Boolean);
    }
    return data
      .filter(t => t && (t.name || t.id || t.uid))
      .map(normalizeTacticShape)
      .filter(Boolean);
  }
  const tactics = data?.tactics;
  if (!Array.isArray(tactics)) return [];
  return tactics
    .filter(t => t && (t.name || t.id || t.uid))
    .map(normalizeTacticShape)
    .filter(Boolean);
}

function tryRecoverMitreTacticsFromWrappedObject(obj, catalog) {
  if (obj == null || typeof obj !== 'object') return [];
  const candidates = gatherMitreNameLineStringsFromObject(obj);
  candidates.sort((a, b) => b.split(/\r?\n/).length - a.split(/\r?\n/).length);
  const cat = Array.isArray(catalog) ? catalog : EMBEDDED_FALLBACK_CATALOG;
  for (const s of candidates) {
    const t = parseMitreNameLinesToTactics(s, cat);
    if (t.length > 0) return t;
  }
  return [];
}

function parseJsonWithMitreRecovery(data, catalog) {
  const parsed = parseFieldJsonPayload(data, catalog);
  if (data != null && typeof data === 'object' && (parsed.length === 0 || tacticsLookLikeEmptyShellColumns(parsed))) {
    const recovered = tryRecoverMitreTacticsFromWrappedObject(data, catalog);
    if (recovered.length > 0) return recovered;
  }
  return parsed;
}

/** Parse record field raw value into tactics[] (uses catalog for name-line resolution). */
function parseMitreFieldRaw(raw, catalog) {
  raw = unwrapRecordField(raw);
  if (raw == null || raw === '') return [];
  const cat = Array.isArray(catalog) ? catalog : EMBEDDED_FALLBACK_CATALOG;

  if (typeof raw === 'string') {
    const trimmed = raw.trim();
    if (!trimmed) return [];
    const tryJsonFirst = trimmed.startsWith('{') || trimmed.startsWith('[');
    if (tryJsonFirst) {
      try {
        return parseJsonWithMitreRecovery(JSON.parse(raw), cat);
      } catch {
        if (isMitreNameLinesString(raw)) return parseMitreNameLinesToTactics(raw, cat);
        return [];
      }
    }
    if (isMitreNameLinesString(raw)) return parseMitreNameLinesToTactics(raw, cat);
    try {
      return parseJsonWithMitreRecovery(JSON.parse(raw), cat);
    } catch {
      return [];
    }
  }

  if (typeof raw === 'object') {
    return parseJsonWithMitreRecovery(raw, cat);
  }
  return [];
}

function tacticsToAlertMitreArray(tactics) {
  const out = [];
  for (const tac of tactics || []) {
    const tId = tac.id != null ? String(tac.id).trim() : '';
    const tName = String(tac.name ?? tId).trim() || tId || 'Tactic';
    if (!tId && !tName) continue;
    for (const tech of tac.techniques || []) {
      if (!tech?.id && !tech?.name) continue;
      out.push({
        tactics: [{ uid: tId, name: tName }],
        technique: {
          uid: String(tech.id ?? '').trim() || String(tech.name ?? ''),
          name: String(tech.name ?? tech.id ?? '').trim() || 'Technique'
        }
      });
    }
  }
  return out;
}

/** Deep clone tactics from the record so merges never drop fields (`summary`, custom keys, long text). */
function cloneTacticsList(tactics) {
  try {
    return JSON.parse(JSON.stringify(tactics || []));
  } catch {
    return (tactics || []).map(t => ({
      ...t,
      techniques: (t.techniques || []).map(tech => ({
        ...tech,
        procedures: Array.isArray(tech.procedures) ? [...tech.procedures] : []
      }))
    }));
  }
}

/** `procedures` is always `string[]`. */
function coerceProcedureStrings(raw) {
  if (raw == null) return [];
  if (typeof raw === 'string') return raw.trim() ? [raw.trim()] : [];
  if (!Array.isArray(raw)) return [];
  return raw
    .map(p => {
      if (typeof p === 'string') return p.trim();
      if (p && typeof p === 'object') return String(p.value ?? p.name ?? p.text ?? '').trim();
      return String(p ?? '').trim();
    })
    .filter(Boolean);
}

/**
 * Canonical technique shape: `{ id, name, procedures }`.
 * Ignores legacy `description` / `summary` on read. Coerces object/array procedure entries to strings.
 */
function normalizeTechniqueShape(tech) {
  if (tech == null) return null;
  if (typeof tech === 'string' || typeof tech === 'number') {
    const s = String(tech).trim();
    if (!s) return null;
    return { id: s, name: s, procedures: [] };
  }
  if (typeof tech !== 'object') return null;
  const rawId = tech.uid ?? tech.id;
  const id = rawId != null ? String(rawId).trim() : '';
  const name = String(tech.name ?? tech.title ?? '').trim() || 'Technique';
  if (!id && !name) return null;
  const procedures = coerceProcedureStrings(tech.procedures);
  return { id, name, procedures };
}

function normalizeTacticShape(tactic) {
  if (!tactic || typeof tactic !== 'object') return null;
  const rawTid = tactic.uid ?? tactic.id;
  const id = rawTid != null ? String(rawTid).trim() : '';
  const name = String(tactic.name ?? '').trim();
  if (!id && !name) return null;
  let techList = tactic.techniques;
  if (!Array.isArray(techList) && tactic.technique != null) {
    techList = [tactic.technique];
  }
  const techniques = (Array.isArray(techList) ? techList : [])
    .map(normalizeTechniqueShape)
    .filter(Boolean);
  return {
    id,
    name: name || id || 'Tactic',
    techniques
  };
}

function sortTacticsByCatalogOrder(tactics, catalog) {
  const cat = catalog || EMBEDDED_FALLBACK_CATALOG;
  const order = new Map(cat.map((t, i) => [t.id, i]));
  return [...tactics].sort((a, b) => (order.get(a.id) ?? 999) - (order.get(b.id) ?? 999));
}

function sortTechniquesForTactic(tacticId, techniques, catalog) {
  const cat = catalog || EMBEDDED_FALLBACK_CATALOG;
  const tac = cat.find(t => t.id === tacticId);
  if (!tac) {
    return [...techniques].sort((a, b) =>
      String(a.id).localeCompare(String(b.id), undefined, { numeric: true })
    );
  }
  const order = new Map(tac.techniques.map((t, i) => [t.id, i]));
  return [...techniques].sort((a, b) => (order.get(a.id) ?? 999) - (order.get(b.id) ?? 999));
}

const baseConfig = {
  /**
   * Application field **key** for TTPs. Omit to auto-detect `mitre-attack-techniques` vs `mitre-attack-technique`
   * from the current record (see `_getMitreFieldKey`). Set only when your field uses a different key.
   */
  recordFieldKey: null,
  /**
   * Optional Turbine field **UUID** (from Application → Fields). Use when `updateRecordValue(key)` fails with
   * `reading 'id'` because `contextData.application.fields` omits this field — the host still resolves `setValue` by id.
   */
  recordFieldId: null,
  /**
   * How TTP data is stored on the record field:
   * - `canonical` — `{ tactics: [ { id, name, techniques: [...] } ] }` or a root array of those tactics.
   * - `alert_mitre_array` — `[ { tactics: [{ uid, name }], technique: { uid, name } }, ... ]` (raw alert/case shape).
   * - `mitre_name_lines` — multiline plain text: each line `Tactic name / Technique name` (ids resolved from STIX catalog when possible).
   * - `swimlane_string_list` — multi-value string field: save as **`string[]`** of `Tactic / Technique` lines by default; read supports **`string[]`** or ListItem `{ value, id?, $type? }[]` from API.
   * - `auto` — detect from non-empty payload; empty `mitre-attack-techniques`-style keys default to `swimlane_string_list` for new writes.
   */
  recordDataShape: 'auto',
  /** Set true if the target field stores JSON as a string (plain text field). */
  persistFieldAsJsonString: false,
  /**
   * When true, `swimlane_string_list` saves `{ value, id? }[]` instead of **`string[]`**. Default **false** —
   * Turbine `setValue` usually expects each list entry to be a **plain string** (see `formatListItem` / `.trim()`).
   */
  mitreSwimlaneSaveAsListObjects: false,
  /**
   * When true (default), Remove from case uses `window.confirm` before removing one TTP or clearing all.
   * Set **false** to persist immediately with no browser dialog.
   */
  confirmRemoveFromCase: true,
  /**
   * When `confirmRemoveFromCase` is true, how to ask for confirmation:
   * - **`dialog`** (default) — in-widget **`swim-dialog`** from `swim-ui.js` (same design system as ngx-ui modals; no Angular `DialogService`).
   * - **`native`** — blocking `window.confirm` (opt-in only).
   *
   * Custom Turbine widgets are **not** Angular components: `@swimlane/ngx-ui` **`DialogService`** / `ng-template` cannot run here.
   */
  removeConfirmPresentation: 'dialog',
  /**
   * When true (default), fetch full enterprise ATT&CK from `mitreStixJsonUrl` for the picker (all TTPs MITRE ships in that bundle).
   * When false, picker uses an empty embedded catalog (offline / air-gapped — no tactics until STIX is enabled or data exists on the record).
   */
  loadFullMitreCatalog: true,
  /** Override STIX bundle URL (must be CORS-accessible to the Turbine origin). */
  mitreStixJsonUrl: DEFAULT_MITRE_STIX_JSON_URL,
  /**
   * Max width (px) for each tactic/technique `swim-select` in the picker (default 520).
   * Wider values reduce ellipsis truncation in the dropdown list.
   */
  pickerSelectMaxWidth: null
};

